window.BEGRIPPEN=[
 {term:'Aankoopmakelaar',uitleg:`Makelaar die de koper begeleidt bij het zoeken, beoordelen en onderhandelen over een woning. Staat los van de financiering, maar de afspraken in de koopovereenkomst (zoals financieringsvoorbehoud en leverdatum) zijn belangrijk voor het hypotheekadvies.`,zoek:['aankoopmakelaar','aankoopbegeleiding']},
 {term:'Aanmerkelijk belang',uitleg:`Belang van ten minste vijf procent in een vennootschap. Voordelen uit dit belang, zoals dividend en verkoopwinst, worden belast in box 2.`,zoek:['aanmerkelijk belang','ab-houder','aanmerkelijkbelanghouder']},
 {term:'Aanvraagbericht (HDN)',uitleg:`Gestandaardiseerd digitaal bericht waarmee een adviseur via het HDN-netwerk een hypotheekaanvraag naar een geldverstrekker stuurt. De geldverstrekker reageert met een offerte- of statusbericht.`,zoek:['aanvraagbericht','hdn-berichten','statusbericht']},
 {term:'Achteraf betalen',uitleg:`Betaalmethode waarbij de consument na aankoop pas later betaalt, al dan niet in termijnen. Kan leiden tot betalingsachterstanden en valt onder de herziene Europese consumentenkredietrichtlijn.`,zoek:['achteraf betalen','buy now pay later','bnpl']},
 {term:'Achtergestelde lening',uitleg:`Lening die bij faillissement of executie pas wordt terugbetaald nadat andere schuldeisers zijn voldaan. Wordt soms gebruikt bij een starterslening of familiehypotheek.`,zoek:['achtergestelde lening','achterstelling','achtergesteld']},
 {term:'Adviesbox Online',uitleg:`Adviespakket voor hypotheek- en financieel advies. Klantgegevens uit eBlinqx exporteer je naar Adviesbox Online via een HBX-bestand; de koppeling werkt met een GUID die je eenmalig in beide pakketten instelt.`,zoek:['adviesbox']},
 {term:'Adviesrapport',uitleg:`Schriftelijke vastlegging van het advies aan de klant, met de uitgangspunten, de overwegingen, de gekozen oplossing en de risico's. Onderdeel van het klantdossier en belangrijk bewijs bij klachten en toezicht.`,zoek:['adviesrapport','adviesverslag','adviesmemo']},
 {term:'Afkoop klein pensioen',uitleg:`Eenmalige uitbetaling van een pensioenaanspraak die onder de wettelijke afkoopgrens ligt. Dit is alleen onder wettelijke voorwaarden mogelijk; de uitkering is belast in box 1.`,zoek:['afkoop klein pensioen','afkoopgrens','klein pensioen afkopen']},
 {term:'Afkoopwaarde',uitleg:`Bedrag dat een verzekeraar uitkeert bij voortijdige beëindiging van een verzekering met opgebouwde waarde, zoals een kapitaal- of lijfrenteverzekering. Afkoop kan fiscale gevolgen hebben, bijvoorbeeld bij een lijfrente of een polis onder overgangsrecht.`,zoek:['afkoopwaarde','afkopen','afkoop polis']},
 {term:'Aflossingseis',uitleg:`Voorwaarde voor renteaftrek op eigenwoningschuld die vanaf 2013 is aangegaan: de lening moet contractueel in maximaal 360 maanden ten minste annuïtair worden afgelost en volgens schema worden afgelost. Wordt niet aan de eis voldaan, dan vervalt de aftrek voor het betreffende deel.`,zoek:['aflossingseis','aflosverplichting','aflossingsverplichting']},
 {term:'Aflossingsvrije hypotheek',uitleg:`Hypotheekvorm waarbij gedurende de looptijd niet wordt afgelost, zodat de hoofdsom aan het einde volledig openstaat. Voor leningen die vanaf 2013 zijn aangegaan is de rente niet aftrekbaar, tenzij overgangsrecht van toepassing is.`,zoek:['aflossingsvrij','aflossingsvrije','aflosvrij']},
 {term:'AFM (Autoriteit Financiële Markten)',uitleg:`Gedragstoezichthouder op de Nederlandse financiële markten. De AFM ziet onder meer toe op advies, bemiddeling, informatieverstrekking en het vergunningstelsel van financiële dienstverleners op grond van de Wft.`,zoek:['afm','autoriteit financiële markten','autoriteit financiele markten']},
 {term:'Aftrekbeperking',uitleg:`Beperking van het tarief waartegen aftrekposten in box 1, zoals hypotheekrente, worden verrekend. Het voordeel van de aftrek is begrensd tot een wettelijk maximumtarief, ook als het inkomen in een hogere schijf valt.`,zoek:['aftrekbeperking','tariefsaanpassing','aftrektarief','beperking aftrek']},
 {term:'AI-verordening',uitleg:`Europese verordening (AI Act) die met een risicogebaseerde aanpak eisen stelt aan het ontwikkelen en gebruiken van AI-systemen. Toepassingen zoals de beoordeling van de kredietwaardigheid van natuurlijke personen gelden als hoog risico.`,zoek:['ai-verordening','ai verordening','ai act','ai-act']},
 {term:'Akte van levering',uitleg:`Notariële akte waarmee de eigendom van een woning van verkoper op koper overgaat. De eigendom gaat pas over na inschrijving van de akte in de openbare registers van het Kadaster.`,zoek:['akte van levering','leveringsakte','transportakte']},
 {term:'Algemene heffingskorting',uitleg:`Korting op de verschuldigde inkomstenbelasting en premie volksverzekeringen voor iedere belastingplichtige. De korting is inkomensafhankelijk en wordt bij hogere inkomens afgebouwd.`,zoek:['algemene heffingskorting','heffingskorting']},
 {term:'Alimentatie',uitleg:`Periodieke bijdrage in het levensonderhoud van een ex-partner (partneralimentatie) of kinderen (kinderalimentatie). Partneralimentatie is voor de betaler aftrekbaar en voor de ontvanger belast; beide vormen tellen mee bij het bepalen van de leencapaciteit.`,zoek:['alimentatie','partneralimentatie','kinderalimentatie']},
 {term:'Allriskverzekering (auto)',uitleg:`Autoverzekering, ook volledig casco genoemd, die naast WA en beperkt casco ook schade aan de eigen auto door eigen schuld dekt. Vooral gebruikelijk bij nieuwe en waardevolle auto's.`,zoek:['allrisk','all risk','volledig casco']},
 {term:'Annuïtair dalende dekking',uitleg:`ORV-dekking die in hetzelfde tempo daalt als de schuld van een annuïteitenhypotheek. Goedkoper dan een gelijkblijvende dekking, terwijl de dekking aansluit bij de resterende schuld.`,zoek:['annuïtair dalend','annuitair dalend','dalende dekking']},
 {term:'Annuïteitenhypotheek',uitleg:`Hypotheekvorm waarbij de bruto maandlast bij gelijkblijvende rente gelijk blijft, terwijl het renteaandeel daalt en het aflossingsdeel stijgt. Bij volledige aflossing binnen 30 jaar voldoet deze vorm aan de aflossingseis.`,zoek:['annuïteit','annuitair','annuïtair','annuïteitenhypotheek','annuiteitenhypotheek']},
 {term:'Annuleringsverzekering',uitleg:`Verzekering die de kosten vergoedt als een reis of evenement om een verzekerde reden, zoals ziekte of overlijden van een familielid, moet worden geannuleerd of afgebroken.`,zoek:['annuleringsverzekering','annulering']},
 {term:'Anw (Algemene nabestaandenwet)',uitleg:`Volksverzekering die onder strikte voorwaarden een uitkering geeft aan een nabestaande partner en aan wezen. De partneruitkering is onder meer afhankelijk van de zorg voor een jong kind of arbeidsongeschiktheid en is inkomensafhankelijk.`,zoek:['anw','algemene nabestaandenwet','anw-uitkering']},
 {term:'Anw-hiaatverzekering',uitleg:`Verzekering die een uitkering doet aan de nabestaande partner wanneer geen of slechts een beperkte Anw-uitkering wordt ontvangen. Vaak aangeboden als aanvulling op een pensioenregeling van de werkgever.`,zoek:['anw-hiaat','anw hiaat','anw-gat','anw-hiaatverzekering']},
 {term:'AOV (arbeidsongeschiktheidsverzekering)',uitleg:`Particuliere verzekering, met name voor zelfstandigen, die een uitkering doet bij arbeidsongeschiktheid. Belangrijke kenmerken zijn het arbeidsongeschiktheidscriterium, de eigenrisicotermijn, de eindleeftijd en de verzekerde uitkering.`,zoek:['aov','arbeidsongeschiktheidsverzekering','arbeidsongeschiktheidsverzekeringen']},
 {term:'AOW (Algemene Ouderdomswet)',uitleg:`Volksverzekering die vanaf de AOW-leeftijd een basispensioen uitkeert. Het recht wordt opgebouwd over de 50 jaar voorafgaand aan de AOW-leeftijd, met 2 procent per verzekerd jaar.`,zoek:['aow','aow-leeftijd','aow-uitkering','ouderdomswet']},
 {term:'AOW-leeftijd',uitleg:`Leeftijd waarop de AOW-uitkering ingaat. Is gekoppeld aan de ontwikkeling van de levensverwachting en wordt vijf jaar vooruit vastgesteld; veel pensioenregelingen stemmen de pensioenrichtleeftijd hierop af.`,zoek:['aow-leeftijd','aow leeftijd','pensioenleeftijd']},
 {term:'Appartementsrecht',uitleg:`Aandeel in een gesplitst gebouw dat het recht geeft op exclusief gebruik van een bepaald deel, zoals een appartement. De eigenaar is verplicht lid van de VvE en draagt bij in de kosten van de gemeenschappelijke delen.`,zoek:['appartementsrecht','appartement','appartementsrechten']},
 {term:'Arbeidskorting',uitleg:`Heffingskorting voor wie inkomen uit arbeid heeft. Loopt eerst op met het arbeidsinkomen en wordt bij hogere inkomens weer afgebouwd.`,zoek:['arbeidskorting']},
 {term:'Arbeidsmarktscan',uitleg:`Rapport dat de verdiencapaciteit van een aanvrager met flexibel of onregelmatig inkomen inschat op basis van onder meer opleiding, werkervaring en de vraag op de arbeidsmarkt. Diverse geldverstrekkers accepteren het als onderbouwing van het toetsinkomen.`,zoek:['arbeidsmarktscan']},
 {term:'Arbeidsongeschiktheidspensioen',uitleg:`Aanvulling op de WIA-uitkering vanuit de pensioenregeling van de werkgever bij arbeidsongeschiktheid. Vaak samen met premievrijstelling voor de pensioenopbouw.`,zoek:['arbeidsongeschiktheidspensioen','ao-pensioen']},
 {term:'Autoriteit Persoonsgegevens (AP)',uitleg:`Nederlandse toezichthouder op de naleving van de AVG. Ontvangt meldingen van datalekken en kan boetes opleggen bij overtredingen.`,zoek:['autoriteit persoonsgegevens','privacytoezichthouder']},
 {term:'AVB (aansprakelijkheidsverzekering bedrijven)',uitleg:`Verzekering die de aansprakelijkheid van een onderneming dekt voor schade aan derden door bedrijfsactiviteiten of producten. Beroepsfouten vallen meestal onder een aparte beroepsaansprakelijkheidsverzekering.`,zoek:['avb','bedrijfsaansprakelijkheid','aansprakelijkheidsverzekering bedrijven']},
 {term:'AVG (Algemene verordening gegevensbescherming)',uitleg:`Europese privacywetgeving (GDPR) die regels stelt aan het verwerken van persoonsgegevens, zoals grondslag, doelbinding, dataminimalisatie en beveiliging. Voor adviseurs relevant bij klantdossiers, het delen van gegevens met geldverstrekkers en het bewaren van stukken.`,zoek:['avg','gdpr','privacywet','algemene verordening gegevensbescherming']},
 {term:'AVP (aansprakelijkheidsverzekering particulieren)',uitleg:`Verzekering die schade dekt die de verzekerde of zijn gezinsleden aan anderen of aan andermans spullen toebrengen en waarvoor zij wettelijk aansprakelijk zijn. Opzet en schade met motorrijtuigen zijn uitgesloten.`,zoek:['avp','aansprakelijkheidsverzekering','wa-particulier','aansprakelijkheidsverzekering particulieren']},
 {term:'Bankgarantie',uitleg:`Garantie van een bank aan de verkoper dat de waarborgsom wordt betaald als de koper zijn verplichtingen uit de koopovereenkomst niet nakomt. Wordt vaak gebruikt in plaats van het storten van de waarborgsom bij de notaris.`,zoek:['bankgarantie','bankgaranties']},
 {term:'Bankspaarhypotheek',uitleg:`Hypotheekvorm waarbij niet direct wordt afgelost maar wordt gespaard op een geblokkeerde spaarrekening eigen woning die aan het einde met de lening wordt verrekend. Voor nieuwe eigenwoningschulden sinds 2013 alleen nog fiscaal gefaciliteerd onder overgangsrecht.`,zoek:['bankspaarhypotheek','bankspaarhypotheken','bankspaar']},
 {term:'Banksparen (lijfrente)',uitleg:`Fiscaal gefaciliteerd sparen of beleggen voor een oudedagsvoorziening op een geblokkeerde rekening bij een bank. Inleg is aftrekbaar binnen de jaarruimte; de uitkeringen zijn belast in box 1.`,zoek:['banksparen','lijfrentebeleggingsrecht','bancaire lijfrente']},
 {term:'Bedenktijd koper',uitleg:`Wettelijke bedenktijd van drie dagen voor een consument die een woning koopt, te rekenen vanaf de terhandstelling van de getekende koopovereenkomst. Binnen die termijn kan de koper zonder opgaaf van reden ontbinden.`,zoek:['bedenktijd','bedenktermijn','wettelijke bedenktijd']},
 {term:'Bedrag ineens (pensioen)',uitleg:`Keuzemogelijkheid om op de pensioeningangsdatum maximaal tien procent van de waarde van het ouderdomspensioen in één keer op te nemen. Dit verlaagt het levenslange pensioen en kan gevolgen hebben voor belasting en toeslagen.`,zoek:['bedrag ineens','10% ineens','opname ineens']},
 {term:'Bedrijfsschadeverzekering',uitleg:`Verzekering die het inkomensverlies en de doorlopende vaste kosten van een onderneming vergoedt als het bedrijf stil komt te liggen door een gedekte gebeurtenis, zoals brand.`,zoek:['bedrijfsschadeverzekering','bedrijfsschade','bedrijfsstilstand']},
 {term:'Begunstigde',uitleg:`Persoon of partij die recht heeft op de uitkering van een verzekering, zoals bij een ORV of lijfrente. De begunstiging bepaalt mede de fiscale gevolgen en moet aansluiten bij het doel van de polis.`,zoek:['begunstigde','begunstiging','begunstigingsclausule']},
 {term:'Belangenconflict',uitleg:`Situatie waarin het belang van de adviseur of zijn onderneming kan botsen met het belang van de klant, bijvoorbeeld door beloningen of zakelijke banden met aanbieders. Financiële ondernemingen moeten belangenconflicten signaleren, beheersen en zo nodig melden aan de klant.`,zoek:['belangenconflict','belangenconflicten','belangenverstrengeling']},
 {term:'Beleggingsadvies',uitleg:`Advies over het kopen, verkopen of aanhouden van specifieke financiële instrumenten. Valt onder de MiFID II-regels en vraagt een geschiktheidsbeoordeling op basis van kennis, ervaring, financiële positie en doelstellingen.`,zoek:['beleggingsadvies','geschiktheidsbeoordeling','geschiktheidsrapport']},
 {term:'Beleggingshypotheek',uitleg:`Hypotheekvorm waarbij de lening aflossingsvrij is en gelijktijdig wordt belegd in een gekoppelde beleggingsrekening of -verzekering om de schuld op termijn af te lossen. Het eindresultaat is onzeker en afhankelijk van het rendement.`,zoek:['beleggingshypotheek','beleggingshypotheken']},
 {term:'Bemiddelen',uitleg:`Wft-activiteit waarbij een financiële onderneming werkzaamheden verricht gericht op het tot stand brengen van een overeenkomst tussen een consument en een aanbieder van een financieel product. Voor bemiddelen is een vergunning van de AFM vereist, tenzij een vrijstelling geldt.`,zoek:['bemiddelen','bemiddelaar','bemiddelingsactiviteit']},
 {term:'Beneficiaire aanvaarding',uitleg:`Aanvaarding van een nalatenschap onder het voorrecht van boedelbeschrijving. De erfgenaam is in beginsel alleen aansprakelijk voor schulden van de nalatenschap tot de waarde van de bezittingen daarin.`,zoek:['beneficiaire aanvaarding','beneficiair aanvaarden','voorrecht van boedelbeschrijving']},
 {term:'Beperkt casco',uitleg:`Autoverzekering die naast de WA-dekking schade aan de eigen auto dekt door onder meer diefstal, brand, storm, ruitschade en botsing met dieren. Eigen schuld bij een aanrijding valt er niet onder.`,zoek:['beperkt casco','wa+','wa plus','wa beperkt casco']},
 {term:'Beperkte gemeenschap van goederen',uitleg:`Standaard huwelijksvermogensregime voor huwelijken en geregistreerde partnerschappen vanaf 1 januari 2018. Voorhuwelijks vermogen en erfenissen en schenkingen blijven privé; wat tijdens het huwelijk wordt opgebouwd is gemeenschappelijk.`,zoek:['beperkte gemeenschap','beperkte gemeenschap van goederen']},
 {term:'Bereidstellingsprovisie',uitleg:`Vergoeding die een geldverstrekker in rekening kan brengen wanneer de hypotheek na afloop van de offertetermijn nog niet is gepasseerd en het aanbod wordt verlengd. Sommige geldverstrekkers rekenen dit ook over het nog niet opgenomen deel van een bouwdepot.`,zoek:['bereidstellingsprovisie','bereidstellingsrente','bereidstelling']},
 {term:'Beroepsaansprakelijkheidsverzekering',uitleg:`Verzekering die schade dekt als gevolg van beroepsfouten van een adviseur of bemiddelaar. Voor adviseurs en bemiddelaars met een Wft-vergunning is een passende beroepsaansprakelijkheidsverzekering verplicht.`,zoek:['beroepsaansprakelijkheid','beroepsaansprakelijkheidsverzekering','bav']},
 {term:'Beroepsarbeidsongeschiktheid',uitleg:`Dekkingscriterium bij een AOV waarbij arbeidsongeschiktheid wordt beoordeeld ten opzichte van het eigen beroep. Ruimer dan dekking op basis van passende of gangbare arbeid, en daardoor duurder.`,zoek:['beroepsarbeidsongeschiktheid','eigen beroep','beroepsdefinitie']},
 {term:'Beschikbare premieregeling',uitleg:`Pensioenregeling waarin de werkgever een vaste of leeftijdsafhankelijke premie betaalt die wordt belegd; de hoogte van het pensioen hangt af van het rendement en de inkooptarieven. Een vorm van premieovereenkomst.`,zoek:['beschikbare premieregeling','bpr','defined contribution']},
 {term:'Beslagvrije voet',uitleg:`Deel van het inkomen waarop een schuldeiser geen beslag mag leggen, zodat de schuldenaar in zijn noodzakelijke levensonderhoud kan voorzien. De berekening is wettelijk vastgelegd.`,zoek:['beslagvrije voet','loonbeslag','beslag']},
 {term:'Bestuurdersaansprakelijkheidsverzekering',uitleg:`Verzekering die bestuurders en commissarissen dekt tegen persoonlijke aansprakelijkheid voor fouten in hun functie. Relevant voor DGA's en bestuurders van stichtingen en verenigingen.`,zoek:['bestuurdersaansprakelijkheid','d&o','d&o-verzekering']},
 {term:'Bestuurlijke boete',uitleg:`Geldboete die een toezichthouder, zoals de AFM, DNB of de AP, kan opleggen bij overtreding van wet- en regelgeving. Wordt in de regel openbaar gemaakt.`,zoek:['bestuurlijke boete','boete afm']},
 {term:'Betalingsachterstand',uitleg:`Situatie waarin een klant de verschuldigde termijnen niet (volledig) op tijd betaalt. Bij hypotheken en kredieten kan dit leiden tot een BKR-registratie, aanmaningskosten en uiteindelijk opeising van de lening.`,zoek:['betalingsachterstand','betalingsachterstanden','achterstand']},
 {term:'Betrouwbaarheidstoetsing',uitleg:`Toetsing door de AFM of DNB van de betrouwbaarheid van dagelijks beleidsbepalers en andere sleutelfunctionarissen, op basis van antecedenten. Daarnaast worden beleidsbepalers op geschiktheid getoetst.`,zoek:['betrouwbaarheidstoetsing','geschiktheidstoetsing','antecedenten']},
 {term:'BEW (beleggingsrecht eigen woning)',uitleg:`Geblokkeerde beleggingsrekening die bestemd is voor aflossing van de eigenwoningschuld. Onder overgangsrecht kon de waarde onder voorwaarden vrijgesteld zijn van inkomstenbelasting.`,zoek:['bew','beleggingsrecht eigen woning']},
 {term:'Bewaartermijn',uitleg:`Periode gedurende welke gegevens moeten of mogen worden bewaard. Wet- en regelgeving zoals de Wft, de Wwft en fiscale regels stellen minimumtermijnen, terwijl de AVG vraagt persoonsgegevens niet langer te bewaren dan nodig.`,zoek:['bewaartermijn','bewaartermijnen','bewaarplicht']},
 {term:'Bgfo (Besluit Gedragstoezicht financiële ondernemingen Wft)',uitleg:`Algemene maatregel van bestuur waarin de gedragsregels uit de Wft nader zijn uitgewerkt, onder meer over informatieverstrekking, vakbekwaamheid, kredietwaardigheidstoetsing en advies. Samen met de Wft het centrale kader voor gedragstoezicht.`,zoek:['bgfo','besluit gedragstoezicht']},
 {term:'Bijleenregeling',uitleg:`Fiscale regel die bepaalt dat bij aankoop van een nieuwe eigen woning de eigenwoningreserve uit de verkoop van een vorige woning in mindering komt op de maximale eigenwoningschuld. Over het deel dat daardoor niet als eigenwoningschuld kwalificeert, is de rente niet aftrekbaar in box 1.`,zoek:['bijleenregeling','bijleenregel']},
 {term:'Bijzonder partnerpensioen',uitleg:`Partnerpensioen dat bij scheiding wordt afgesplitst voor de ex-partner en dat wordt uitgekeerd als de deelnemer overlijdt. Is gebaseerd op het tot de scheiding opgebouwde partnerpensioen.`,zoek:['bijzonder partnerpensioen','bijzonder nabestaandenpensioen']},
 {term:'Bindend advies (Kifid)',uitleg:`Uitspraak van de Geschillencommissie van het Kifid waaraan partijen gebonden zijn als zij daarvoor hebben gekozen. Hoger beroep is mogelijk bij de Commissie van Beroep van het Kifid.`,zoek:['bindend advies','geschillencommissie','commissie van beroep']},
 {term:'BKR (Bureau Krediet Registratie)',uitleg:`Stichting die het Centraal Krediet Informatiesysteem beheert, waarin kredieten en betalingsachterstanden van consumenten worden geregistreerd. Geldverstrekkers raadplegen deze registratie bij de beoordeling van een krediet- of hypotheekaanvraag.`,zoek:['bkr','bkr-registratie','bkr-toetsing','cki']},
 {term:'BKR-codering',uitleg:`Aanduiding bij een kredietregistratie in het Centraal Krediet Informatiesysteem die aangeeft of er sprake is van een achterstand of een bijzonderheid. Een negatieve codering maakt een hypotheek of krediet vaak lastig verkrijgbaar.`,zoek:['bkr-codering','a-codering','achterstandscodering','negatieve registratie']},
 {term:'Boeterente (vergoeding vervroegde aflossing)',uitleg:`Vergoeding die de geldverstrekker in rekening brengt bij aflossing boven het boetevrije deel tijdens de rentevaste periode, ter compensatie van het renteverlies. De berekening is gebonden aan wettelijke regels; bij verkoop van de woning of overlijden geldt doorgaans geen vergoeding.`,zoek:['boeterente','vergoeding vervroegde aflossing','vervroegd aflossen','vervroegde aflossing','extra aflossen']},
 {term:'Boetevrije aflossing',uitleg:`Deel van de lening dat de klant jaarlijks extra mag aflossen zonder vergoeding voor vervroegde aflossing te betalen. Het percentage en de grondslag verschillen per geldverstrekker.`,zoek:['boetevrij aflossen','boetevrije aflossing','boetevrije ruimte']},
 {term:'Bonus-malusladder',uitleg:`Systeem waarmee de no-claimkorting op een autoverzekering stijgt bij schadevrije jaren en daalt na een geclaimde schade. Elke verzekeraar hanteert een eigen ladder.`,zoek:['bonus-malus','bonus malus','no-claimkorting','no claim','schadevrije jaren']},
 {term:'Borgtocht',uitleg:`Overeenkomst waarbij iemand (de borg) zich tegenover een schuldeiser verplicht de schuld van een ander te betalen als die zijn verplichtingen niet nakomt. Voor een particuliere borgtocht is vaak toestemming van de echtgenoot of geregistreerde partner nodig.`,zoek:['borgtocht','borgstelling','borg staan','borg']},
 {term:'Borgtochtprovisie',uitleg:`Eenmalige vergoeding die de consument betaalt voor een hypotheek met Nationale Hypotheek Garantie. De borgtochtprovisie geldt fiscaal als aftrekbare financieringskosten.`,zoek:['borgtochtprovisie','nhg-kosten','kosten nhg']},
 {term:'Bouwdepot',uitleg:`Deel van de hypotheek dat op een geblokkeerde rekening wordt aangehouden en op basis van facturen wordt uitbetaald voor nieuwbouw, verbouwing of verduurzaming. Over het saldo vergoedt de geldverstrekker doorgaans rente.`,zoek:['bouwdepot','bouwdepots','verbouwingsdepot']},
 {term:'Bouwkundige keuring',uitleg:`Onderzoek naar de bouwkundige staat van een woning, met een overzicht van gebreken en geraamde herstelkosten. Kan aanleiding zijn om kosten voor verbetering mee te financieren of de koop te heroverwegen.`,zoek:['bouwkundige keuring','bouwkundig rapport','bouwkeuring']},
 {term:'Box 1',uitleg:`Box in de inkomstenbelasting voor belastbaar inkomen uit werk en woning. Hieronder vallen onder meer loon, winst, het eigenwoningforfait, de aftrekbare hypotheekrente en de lijfrentepremieaftrek.`,zoek:['box 1','box1']},
 {term:'Box 2',uitleg:`Box in de inkomstenbelasting voor inkomen uit aanmerkelijk belang, zoals dividend en vervreemdingsvoordelen uit een eigen bv. Relevant voor de dga, bijvoorbeeld bij financiering van de eigen woning vanuit de bv.`,zoek:['box 2','box2','aanmerkelijk belang']},
 {term:'Box 3',uitleg:`Box in de inkomstenbelasting voor inkomen uit sparen en beleggen. Schulden die niet als eigenwoningschuld kwalificeren, zoals een niet-aftrekbaar deel van een hypotheek, kunnen hier als schuld meetellen; het stelsel is na rechtspraak van de Hoge Raad in herziening.`,zoek:['box 3','box3','vermogensrendementsheffing']},
 {term:'Broodfonds',uitleg:`Groep zelfstandigen die elkaar bij langdurige ziekte gedurende een beperkte periode een schenking doen uit gezamenlijk opgebouwde reserves. Is geen verzekering en biedt geen dekking voor langdurige arbeidsongeschiktheid.`,zoek:['broodfonds','broodfondsen']},
 {term:'Buy-to-let hypotheek',uitleg:`Financiering voor de aankoop van een woning die wordt verhuurd. Geldverstrekkers kijken vooral naar de huurinkomsten, de waarde in verhuurde staat en de eigen inbreng; de rente is niet aftrekbaar in box 1 en de woning valt in box 3.`,zoek:['buy-to-let','buy to let','verhuurhypotheek','beleggingspand']},
 {term:'CCD2 (herziene Consumentenkredietrichtlijn)',uitleg:`Europese richtlijn die de regels voor consumentenkrediet moderniseert, onder meer voor kleine kredieten, achteraf betalen en de beoordeling van de kredietwaardigheid. Lidstaten moeten de regels vanaf 20 november 2026 toepassen.`,zoek:['ccd2','ccd','consumentenkredietrichtlijn','consumer credit directive']},
 {term:'CIS (Stichting Centraal Informatie Systeem)',uitleg:`Stichting die namens verzekeraars registers bijhoudt van onder meer schademeldingen en fraudesignalen. Verzekeraars raadplegen het CIS bij acceptatie en schadebehandeling.`,zoek:['cis','stichting cis','cis-register']},
 {term:'Clausulering',uitleg:`Beperking of uitsluiting in een polis naar aanleiding van medische of andere risicofactoren bij acceptatie, bijvoorbeeld bij een AOV of ORV. De adviseur moet de gevolgen van een clausule expliciet met de klant bespreken.`,zoek:['clausulering','clausule','uitsluitingsclausule']},
 {term:'Cliëntenonderzoek (CDD)',uitleg:`Verplicht onderzoek op grond van de Wwft naar de identiteit van de cliënt, de uiteindelijk belanghebbende en het doel en de aard van de zakelijke relatie. De diepgang hangt af van het risico: vereenvoudigd, standaard of verscherpt.`,zoek:['cliëntenonderzoek','clientenonderzoek','cdd','customer due diligence']},
 {term:'Complex product',uitleg:`Financieel product dat volgens de Wft-regelgeving bijzondere eisen stelt aan informatieverstrekking en vakbekwaamheid, zoals hypothecair krediet en beleggingsverzekeringen. Voor bepaalde complexe en impactvolle producten geldt een provisieverbod.`,zoek:['complex product','complexe producten','complexe product']},
 {term:'Compliance officer',uitleg:`Functionaris binnen een financiële onderneming die toeziet op de naleving van wet- en regelgeving en interne gedragsregels. Bij kleinere adviespraktijken kan deze functie worden uitbesteed.`,zoek:['compliance officer','compliance-officer','compliancefunctie']},
 {term:'Consumptief krediet',uitleg:`Verzamelterm voor kredieten aan consumenten die niet door een hypotheekrecht zijn gedekt, zoals een persoonlijke lening of doorlopend krediet. Bij een hypotheekaanvraag tellen lopende kredieten mee in de berekening van de maximale hypotheek.`,zoek:['consumptief krediet','consumptieve kredieten','consumptieve lening']},
 {term:'Contra-expertise',uitleg:`Tweede, onafhankelijke beoordeling door een eigen deskundige van de verzekerde, bijvoorbeeld bij een schadevaststelling of taxatie. Polisvoorwaarden regelen vaak of en tot welk bedrag de kosten worden vergoed.`,zoek:['contra-expertise','contra expertise','tegenexpertise']},
 {term:'Creditcard',uitleg:`Betaalkaart met een kredietlimiet die maandelijks wordt verrekend. Een creditcard met een limiet wordt bij het BKR geregistreerd en telt mee bij de hypotheektoets.`,zoek:['creditcard','credit card','kredietkaart']},
 {term:'Cyberverzekering',uitleg:`Verzekering voor schade en kosten na een cyberincident, zoals een datalek of hack, waaronder herstelkosten, bedrijfsschade en aansprakelijkheid. Relevant voor adviesbedrijven die veel persoonsgegevens verwerken.`,zoek:['cyberverzekering','cyberrisico','cyber']},
 {term:'Dagelijks beleidsbepaler',uitleg:`Persoon die het dagelijks beleid van een financiële onderneming bepaalt, zoals een directeur. Moet vooraf door de AFM of DNB worden getoetst op betrouwbaarheid en geschiktheid.`,zoek:['dagelijks beleidsbepaler','dagelijkse beleidsbepalers','beleidsbepaler']},
 {term:'Dagwaarde',uitleg:`Waarde van een zaak op het moment van de schade, rekening houdend met ouderdom, slijtage en gebruik. Bij uitkering op dagwaardebasis is de vergoeding lager dan de nieuwwaarde.`,zoek:['dagwaarde','dagwaardevergoeding']},
 {term:'Datalek',uitleg:`Inbreuk op de beveiliging waardoor persoonsgegevens verloren gaan of onrechtmatig worden verwerkt, bijvoorbeeld door een verkeerd verzonden e-mail of hack. Een datalek met risico voor betrokkenen moet binnen 72 uur na ontdekking aan de AP worden gemeld.`,zoek:['datalek','datalekken','meldplicht datalekken']},
 {term:'Dekkingsgraad',uitleg:`Verhouding tussen het vermogen van een pensioenfonds en de pensioenverplichtingen. De beleidsdekkingsgraad, een gemiddelde over de afgelopen maanden, is bepalend voor besluiten over indexatie en korting.`,zoek:['dekkingsgraad','beleidsdekkingsgraad','actuele dekkingsgraad']},
 {term:'Desktoptaxatie',uitleg:`Waardebepaling van een woning op basis van een rekenmodel en beschikbare data, zonder bezichtiging door een taxateur. Geldverstrekkers accepteren deze modelmatige waardering alleen onder voorwaarden, bijvoorbeeld bij een lage lening ten opzichte van de woningwaarde.`,zoek:['desktoptaxatie','modelmatige waardering','modelmatige waardebepaling','avm']},
 {term:'DGA (directeur-grootaandeelhouder)',uitleg:`Bestuurder die een aanmerkelijk belang heeft in de bv waarvoor hij werkt. Voor de dga gelden specifieke regels voor inkomensbepaling bij een hypotheekaanvraag en eigen fiscale aandachtspunten, zoals lenen van de eigen bv.`,zoek:['dga','directeur-grootaandeelhouder','directeur grootaandeelhouder']},
 {term:'Dienstenwijzer',uitleg:`Document waarin een financieel dienstverlener informatie geeft over zijn organisatie, dienstverlening, beloning en klachtafhandeling. De term wordt in de praktijk nog gebruikt voor de precontractuele informatie die de adviseur aan de klant verstrekt. Voor producten onder het provisieverbod geef je sinds 1 april 2023 de vergelijkingskaart; wettelijke informatie zoals je klachtenprocedure, Kifid-aansluiting en AFM-registratie geef je daarnaast, bijvoorbeeld via je website of opdrachtbevestiging.`,zoek:['dienstenwijzer']},
 {term:'Dienstverleningsdocument (dvd)',uitleg:`Verouderd begrip. Tot 1 april 2023 het verplichte document waarmee de adviseur bij producten onder het provisieverbod vooraf informatie gaf over zijn dienstverlening en kosten. Per 1 april 2023 is het vervangen door de vergelijkingskaart. Werk sjablonen, brieven en websiteteksten bij die nog naar het dienstverleningsdocument verwijzen.`,zoek:['dienstverleningsdocument','dienstverleningsdocumenten','dvd']},
 {term:'DigiD',uitleg:`Inlogmiddel van de overheid waarmee consumenten onder meer bij de Belastingdienst, het UWV en MijnOverheid gegevens kunnen inzien en downloaden. Wordt gebruikt om inkomens- en pensioengegevens op te halen.`,zoek:['digid','mijnoverheid','mijn overheid']},
 {term:'Digitaal ondertekenen',uitleg:`Elektronisch tekenen van documenten zoals offertes en volmachten. Afhankelijk van de vereiste bewijskracht wordt een gewone, geavanceerde of gekwalificeerde elektronische handtekening gebruikt.`,zoek:['digitaal ondertekenen','e-signing','elektronische handtekening','digitale handtekening']},
 {term:'Direct ingaande lijfrente',uitleg:`Lijfrente die direct na storting van een koopsom periodiek gaat uitkeren, bijvoorbeeld uit een vrijgekomen lijfrentekapitaal. Voor de fiscale aftrek gelden voorwaarden aan looptijd en ingangsmoment.`,zoek:['direct ingaande lijfrente','dil','lijfrente-uitkering']},
 {term:'Dividend',uitleg:`Uitkering van winst door een vennootschap aan haar aandeelhouders. Voor een DGA met een aanmerkelijk belang valt dividend in box 2.`,zoek:['dividend','dividenduitkering','winstuitkering']},
 {term:'DNB (De Nederlandsche Bank)',uitleg:`Centrale bank en prudentieel toezichthouder op banken, verzekeraars en pensioenfondsen. Ziet toe op de financiële soliditeit van deze instellingen.`,zoek:['dnb','de nederlandsche bank','nederlandsche bank']},
 {term:'Doorlopend krediet',uitleg:`Kredietvorm met een vaste kredietlimiet waarbinnen de consument geld kan opnemen en terugbetalen, met een variabele rente. Bij een hypotheekaanvraag wordt doorgaans rekening gehouden met een maandlast op basis van de volledige limiet.`,zoek:['doorlopend krediet','doorlopende kredieten','rekening-courantkrediet']},
 {term:'Doorstromer',uitleg:`Huiseigenaar die zijn huidige woning verkoopt en een andere woning koopt. Bij doorstromers spelen onder meer de eigenwoningreserve, de bijleenregeling, overbrugging, dubbele woonlasten en het meenemen van de bestaande hypotheek.`,zoek:['doorstromer','doorstromers','doorstroming']},
 {term:'DORA (Digital Operational Resilience Act)',uitleg:`Europese verordening die sinds januari 2025 eisen stelt aan het beheer van ICT-risico's, incidentmelding en uitbesteding aan ICT-dienstverleners bij financiële instellingen. Kleine en middelgrote verzekeringstussenpersonen vallen er niet onder.`,zoek:['dora','digital operational resilience act']},
 {term:'DPIA (gegevensbeschermingseffectbeoordeling)',uitleg:`Analyse van de privacyrisico's van een gegevensverwerking die verplicht is als de verwerking waarschijnlijk een hoog risico voor betrokkenen oplevert, bijvoorbeeld bij grootschalige verwerking van financiële gegevens of profilering.`,zoek:['dpia','gegevensbeschermingseffectbeoordeling','privacy impact assessment','pia']},
 {term:'Draagplicht',uitleg:`Verdeling tussen medeschuldenaars van wie welk deel van een gezamenlijke schuld onderling draagt, los van de hoofdelijke aansprakelijkheid tegenover de geldverstrekker. Draagplicht is onder meer relevant voor de fiscale aftrek van rente en bij scheiding.`,zoek:['draagplicht']},
 {term:'Dubbele woonlasten',uitleg:`Situatie waarin een consument tijdelijk lasten heeft voor zowel de oude als de nieuwe woning, bijvoorbeeld zolang de oude woning niet is verkocht. Fiscaal en bij de leencapaciteit gelden hiervoor specifieke regels.`,zoek:['dubbele woonlasten','dubbele lasten','dubbele maandlasten']},
 {term:'DUO (Dienst Uitvoering Onderwijs)',uitleg:`Uitvoeringsorganisatie die onder meer de studiefinanciering en studieleningen beheert. Het overzicht van DUO geeft de oorspronkelijke studieschuld die bij de hypotheektoets wordt gebruikt.`,zoek:['duo','dienst uitvoering onderwijs','studiefinanciering']},
 {term:'Duurzaamheidskorting',uitleg:`Rentekorting die sommige geldverstrekkers geven bij een goed energielabel van de woning of na verduurzaming. Voorwaarden en hoogte verschillen per aanbieder.`,zoek:['duurzaamheidskorting','groene korting','energielabelkorting','groene hypotheek']},
 {term:"Duurzaamheidsprofiel",uitleg:`Rapport per woning op Duurzaamheidsprofiel.nl met verduurzamingsmogelijkheden, besparing en de bijbehorende leenruimte. Bedoeld als gespreksstarter in het hypotheekgesprek; voor extra leenruimte telt het geregistreerde energielabel. Zie k332.`,zoek:['duurzaamheidsprofiel','duurzaamheidsprofiel.nl']},
 {term:'Duurzaamheidsvoorkeuren',uitleg:`Voorkeuren van een klant ten aanzien van duurzaamheid die op grond van Europese regelgeving moeten worden uitgevraagd en meegewogen bij advies over verzekeringsgebonden beleggingsproducten en beleggingen. De adviseur legt vast hoe deze voorkeuren in het advies zijn betrokken.`,zoek:['duurzaamheidsvoorkeuren','duurzaamheidsvoorkeur']},
 {term:'EBB (energiebespaarbudget)',uitleg:`Ruimte om binnen de hypotheek extra te lenen voor energiebesparende maatregelen, bovenop de reguliere financieringslast en waarde-eisen. De hoogte is afhankelijk van de normen en het energielabel van de woning.`,zoek:['ebb','energiebespaarbudget']},
 {term:'eBlinqx Hypotheekadvies (Fastlane)',uitleg:`Het adviespakket van Blinqx Verzekering & Hypotheek. eBlinqx Hypotheekadvies en Fastlane (Fastlane Advies) zijn hetzelfde pakket; supportartikelen gebruiken beide namen.`,zoek:['fastlane','eblinqx hypotheekadvies']},
 {term:'EBV (energiebesparende voorzieningen)',uitleg:`Maatregelen die de energieprestatie van een woning verbeteren, zoals isolatie, zonnepanelen of een warmtepomp. Volgens de leennormen kan hiervoor onder voorwaarden extra leenruimte worden benut.`,zoek:['ebv','energiebesparende voorzieningen','energiebesparende maatregelen']},
 {term:'ECB-rente',uitleg:`Beleidsrente van de Europese Centrale Bank. Heeft vooral direct effect op variabele en kort rentevaste hypotheken en op de spaarrente.`,zoek:['ecb-rente','ecb','beleidsrente','europese centrale bank']},
 {term:'Echtscheiding',uitleg:`Ontbinding van een huwelijk door de rechter. Voor het advies zijn onder meer de verdeling van de woning, ontslag uit hoofdelijke aansprakelijkheid, alimentatie, pensioenverevening en de fiscale gevolgen voor de eigenwoningschuld van belang.`,zoek:['echtscheiding','scheiding','scheiden','relatiebeëindiging']},
 {term:'Eed of belofte financiële sector',uitleg:`Verplichte eed of belofte voor medewerkers van financiële ondernemingen die rechtstreeks met klanten te maken hebben of het risicoprofiel kunnen beïnvloeden. Hierin belooft de medewerker onder meer het klantbelang centraal te stellen.`,zoek:['eed','bankierseed','eed of belofte','beroepseed']},
 {term:'eHerkenning',uitleg:`Inlogmiddel waarmee ondernemingen zich digitaal identificeren bij overheidsorganisaties, bijvoorbeeld om aangifte te doen of gegevens te raadplegen.`,zoek:['eherkenning','e-herkenning']},
 {term:'Eigen inbreng',uitleg:`Deel van de aankoop of verbouwing dat de klant uit eigen middelen financiert, zoals spaargeld of een schenking. Omdat kosten koper niet volledig kunnen worden meegefinancierd, is eigen inbreng vaak noodzakelijk.`,zoek:['eigen inbreng','eigen middelen','eigen geld']},
 {term:'Eigen risico',uitleg:`Deel van een schade dat de verzekerde zelf draagt. Een hoger eigen risico leidt doorgaans tot een lagere premie.`,zoek:['eigen risico','eigen bijdrage schade']},
 {term:'Eigenrisicodrager WGA',uitleg:`Werkgever die zelf het risico draagt voor WGA-uitkeringen van (ex-)werknemers in plaats van daarvoor premie aan het UWV te betalen. Wordt vaak herverzekerd bij een verzekeraar.`,zoek:['eigenrisicodrager','erd','eigenrisicodragerschap']},
 {term:'Eigenrisicotermijn',uitleg:`Periode na het begin van arbeidsongeschiktheid of werkloosheid waarover nog geen uitkering wordt gedaan, ook wel wachttijd genoemd. Een langere eigenrisicotermijn verlaagt de premie maar vraagt om voldoende buffer.`,zoek:['eigenrisicotermijn','eigen risicotermijn','wachttijd']},
 {term:'Eigenwoningforfait',uitleg:`Bedrag dat als fictief voordeel uit de eigen woning bij het inkomen in box 1 wordt geteld, berekend als percentage van de WOZ-waarde. Daartegenover staat de aftrek van rente op de eigenwoningschuld.`,zoek:['eigenwoningforfait','ewf','huurwaardeforfait']},
 {term:'Eigenwoningschuld',uitleg:`Schuld die is aangegaan voor de verwerving, verbetering of het onderhoud van de eigen woning en die voldoet aan de fiscale voorwaarden. Alleen over de eigenwoningschuld is rente aftrekbaar in box 1.`,zoek:['eigenwoningschuld','eigenwoningschulden','ews']},
 {term:'Energielabel',uitleg:`Label dat de energieprestatie van een woning aangeeft. Het label kan invloed hebben op de extra leenruimte voor verduurzaming, de rente bij sommige geldverstrekkers en de marktwaarde.`,zoek:['energielabel','energielabels']},
 {term:'Erfbelasting',uitleg:`Belasting die verschuldigd is over wat iemand verkrijgt uit een nalatenschap. Relevant bij nabestaandenplanning, bijvoorbeeld bij de keuze voor een kruislingse ORV.`,zoek:['erfbelasting','successierecht','successierechten']},
 {term:'Erfdienstbaarheid',uitleg:`Last die op een onroerende zaak rust ten behoeve van een andere onroerende zaak, zoals een recht van overpad. Wordt ingeschreven in het Kadaster en kan de waarde en het gebruik van een woning beïnvloeden.`,zoek:['erfdienstbaarheid','erfdienstbaarheden','recht van overpad']},
 {term:'Erfgenaam',uitleg:`Persoon die op grond van de wet of een testament onder algemene titel een deel van de nalatenschap verkrijgt, inclusief de schulden. Een erfgenaam kan zuiver aanvaarden, beneficiair aanvaarden of verwerpen.`,zoek:['erfgenaam','erfgenamen','erfdeel']},
 {term:'Erfpacht',uitleg:`Zakelijk recht om de grond van een ander te gebruiken, meestal tegen een periodieke vergoeding (canon). Erfpachtvoorwaarden, de canon en eventuele afkoop beïnvloeden de financieringslast, de marktwaarde en de acceptatie door geldverstrekkers.`,zoek:['erfpacht','erfpachtcanon','erfpachtgrond','canon']},
 {term:'Erfrecht',uitleg:`Regels over wie na overlijden de bezittingen en schulden van de overledene verkrijgt en onder welke voorwaarden. Opgenomen in Boek 4 van het Burgerlijk Wetboek; afwijken is mogelijk via een testament.`,zoek:['erfrecht','nalatenschap','erfenis']},
 {term:'ESIS (European Standardised Information Sheet)',uitleg:`Gestandaardiseerd Europees informatieblad met de kenmerken en kosten van een aangeboden hypothecair krediet. De aanbieder verstrekt het voorafgaand aan de overeenkomst zodat de consument aanbiedingen kan vergelijken.`,zoek:['esis','esis-formulier','europees gestandaardiseerd informatieblad']},
 {term:'EWR (eigenwoningreserve)',uitleg:`Bij verkoop van een eigen woning de overwaarde, bepaald als verkoopprijs minus verkoopkosten minus de eigenwoningschuld. De eigenwoningreserve beperkt via de bijleenregeling de maximaal aftrekbare schuld voor een volgende woning en vervalt na een bepaalde termijn.`,zoek:['ewr','eigenwoningreserve']},
 {term:'Excessief lenen bij eigen vennootschap',uitleg:`Regeling waarbij schulden van een aanmerkelijkbelanghouder aan zijn eigen vennootschap boven een wettelijke drempel als fictief regulier voordeel in box 2 worden belast. Eigenwoningschulden die aan de voorwaarden voldoen, tellen onder voorwaarden niet mee.`,zoek:['excessief lenen','wet excessief lenen','lenen bij eigen bv']},
 {term:'Executeur',uitleg:`Persoon die in een testament wordt aangewezen om de nalatenschap af te wikkelen, bijvoorbeeld schulden te betalen en legaten uit te keren. De bevoegdheden hangen af van wat in het testament is vastgelegd.`,zoek:['executeur','executeur-testamentair','executele']},
 {term:'Executieveiling',uitleg:`Gedwongen openbare verkoop van een onderpand door de hypotheekhouder als de schuldenaar zijn verplichtingen niet nakomt. De opbrengst is meestal lager dan bij een vrije verkoop, waardoor vaak een restschuld ontstaat.`,zoek:['executieveiling','executoriale verkoop','gedwongen verkoop','veiling woning']},
 {term:'Executiewaarde',uitleg:`Verwachte opbrengst van een woning bij een gedwongen verkoop, doorgaans lager dan de marktwaarde. Wordt in taxatierapporten soms nog vermeld, maar is niet meer leidend voor de maximale hypotheek.`,zoek:['executiewaarde','veilingwaarde']},
 {term:'Execution only',uitleg:`Dienstverlening waarbij een financieel product wordt afgesloten zonder advies. Voor complexe producten zoals hypotheken gelden aanvullende waarborgen, zoals een kennis- en ervaringstoets.`,zoek:['execution only','execution-only','zonder advies']},
 {term:'Explain (comply or explain)',uitleg:`Mogelijkheid voor geldverstrekkers om in individuele gevallen gemotiveerd af te wijken van de leennormen, mits dit verantwoord is en het dossier de onderbouwing bevat. Wordt in de praktijk een explain-hypotheek of explain-aanvraag genoemd.`,zoek:['comply or explain','explain-hypotheek','explain-aanvraag','explain']},
 {term:'Factor A',uitleg:`Jaarlijkse aangroei van het pensioen in een werkgeversregeling, uitgedrukt in een fiscaal getal. Wordt gebruikt om de jaarruimte voor lijfrentepremieaftrek te berekenen en staat op het UPO.`,zoek:['factor a','pensioenaangroei']},
 {term:'Familiehypotheek',uitleg:`Lening voor de eigen woning die wordt verstrekt door familie, bijvoorbeeld ouders. De rente kan aftrekbaar zijn als aan de voorwaarden voor eigenwoningschuld is voldaan, waaronder de aflossingseis en een zakelijke rente.`,zoek:['familiehypotheek','familielening','lenen van ouders','onderhandse lening']},
 {term:'Financial lease',uitleg:`Leasevorm waarbij de lessee economisch eigenaar is en aan het einde van de looptijd juridisch eigenaar kan worden. Voor consumenten is dit een vorm van consumptief krediet met BKR-registratie.`,zoek:['financial lease']},
 {term:'Financieel planner',uitleg:`Adviseur die de totale financiële situatie van een klant integraal in kaart brengt, zoals inkomen, vermogen, pensioen, woning en vermogensoverdracht, en daarover samenhangend advies geeft.`,zoek:['financieel planner','financiële planning','financiele planning','ffp']},
 {term:'Financieringskosten',uitleg:`Kosten die direct samenhangen met het afsluiten van de eigenwoningschuld, zoals advies- en bemiddelingskosten, taxatiekosten, de notariskosten voor de hypotheekakte en de borgtochtprovisie. Deze kosten zijn in het jaar van betaling aftrekbaar in box 1.`,zoek:['financieringskosten','aftrekbare kosten']},
 {term:'Financieringslastpercentage',uitleg:`Percentage van het toetsinkomen dat volgens de leennormen maximaal aan bruto hypotheeklasten mag worden besteed. Het percentage hangt af van de hoogte van het inkomen en de toetsrente en wordt jaarlijks vastgesteld.`,zoek:['financieringslastpercentage','financieringslast','financieringslasten']},
 {term:'Financieringsopzet',uitleg:`Overzicht van alle kosten van de woningaankoop of verbouwing en de wijze van financiering, waaronder koopsom, kosten koper, verbouwing, eigen inbreng en hypotheekbedrag. Vormt de basis van het hypotheekadvies en de aanvraag.`,zoek:['financieringsopzet','financieringsoverzicht']},
 {term:'Fiscaal partnerschap',uitleg:`Fiscale status van gehuwden, geregistreerde partners en onder voorwaarden samenwonenden. Fiscaal partners kunnen bepaalde inkomensbestanddelen, waaronder het saldo van de eigen woning, onderling vrij verdelen.`,zoek:['fiscaal partner','fiscaal partnerschap','fiscale partner','fiscale partners']},
 {term:'FIU-Nederland (Financial Intelligence Unit)',uitleg:`Organisatie waar Wwft-instellingen ongebruikelijke transacties melden. De FIU analyseert de meldingen en kan transacties als verdacht aanmerken en doorgeven aan opsporingsdiensten.`,zoek:['fiu','fiu-nederland','financial intelligence unit','melding ongebruikelijke transactie']},
 {term:'Flexibele premieregeling',uitleg:`Premieregeling onder de Wtp waarin de deelnemer een persoonlijk pensioenvermogen opbouwt en meer keuzes heeft over beleggingsrisico en de uitkeringsfase, met een vaste of variabele uitkering.`,zoek:['flexibele premieregeling','flexibele premieovereenkomst']},
 {term:'FOR (fiscale oudedagsreserve)',uitleg:`Reserve die ondernemers in de inkomstenbelasting konden vormen voor hun oudedagsvoorziening. Nieuwe opbouw is per 2023 beëindigd; de bestaande reserve blijft onder voorwaarden behouden en kan onder meer worden omgezet in een lijfrente.`,zoek:['for','fiscale oudedagsreserve','oudedagsreserve']},
 {term:'Forfaitair rendement',uitleg:`Vast veronderstelde rendementspercentage per vermogenscategorie (banktegoeden, overige bezittingen, schulden) waarmee het belastbare inkomen in box 3 wordt berekend. De percentages worden jaarlijks vastgesteld.`,zoek:['forfaitair rendement','fictief rendement','rendementspercentage']},
 {term:'Franchise',uitleg:`Deel van het salaris waarover geen pensioen wordt opgebouwd, omdat de deelnemer daarvoor al AOW ontvangt. De pensioengrondslag is het pensioengevend salaris min de franchise.`,zoek:['franchise','aow-franchise','pensioengrondslag']},
 {term:'Functionaris voor gegevensbescherming (FG)',uitleg:`Interne toezichthouder op de naleving van de AVG binnen een organisatie. Is verplicht bij overheidsinstanties en bij organisaties die op grote schaal bijzondere gegevens verwerken of mensen stelselmatig volgen.`,zoek:['functionaris gegevensbescherming','functionaris voor gegevensbescherming','dpo']},
 {term:"Funderingscijfer",uitleg:`Indicatief funderingsrisico per adres op een schaal van 2 (zeer hoog risico) tot 8 (zeer laag), opgebouwd uit bouwjaar, bodem, maaiveldhoogte, RVO-aandachtsgebied en grondwater. Geen KCAF-klasse en geen funderingsonderzoek. Zie k352.`,zoek:['funderingscijfer','funderingscijfer.nl']},
 {term:'Gangbare arbeid',uitleg:`Arbeidsongeschiktheidscriterium waarbij wordt beoordeeld of de verzekerde nog algemeen geaccepteerde arbeid kan verrichten die past bij zijn krachten en bekwaamheden. Dit is het ruimste criterium en leidt minder snel tot een uitkering dan beroeps- of passende arbeid.`,zoek:['gangbare arbeid','gangbare-arbeidcriterium','arbeidsongeschiktheidscriterium']},
 {term:'Garantie tegen onderverzekering',uitleg:`Afspraak in een polis dat de verzekeraar bij schade geen beroep doet op onderverzekering, mits het verzekerde bedrag op een voorgeschreven manier is vastgesteld, bijvoorbeeld via een waardemeter.`,zoek:['garantie tegen onderverzekering','onderverzekeringsgarantie','waardemeter']},
 {term:'Gebruikelijk loon',uitleg:`Minimumloon dat een DGA fiscaal moet ontvangen uit zijn vennootschap, gebaseerd op wat gebruikelijk is voor vergelijkbaar werk. Relevant voor de inkomensbepaling bij een hypotheekaanvraag.`,zoek:['gebruikelijk loon','gebruikelijkloonregeling','dga-loon']},
 {term:'Gedragscode Hypothecaire Financieringen',uitleg:`Zelfregulering van geldverstrekkers met regels voor verantwoorde hypotheekverstrekking, zoals over taxatie en informatievoorziening. Veel normen zijn inmiddels opgenomen in wet- en regelgeving.`,zoek:['gedragscode hypothecaire financieringen','ghf']},
 {term:'Gedragstoezicht',uitleg:`Toezicht op de wijze waarop financiële ondernemingen zich gedragen tegenover klanten, zoals informatieverstrekking, zorgvuldig advies en klachtafhandeling. In Nederland uitgevoerd door de AFM; prudentieel toezicht ligt bij DNB.`,zoek:['gedragstoezicht','gedragsregels']},
 {term:'Geldverstrekker',uitleg:`Bank, verzekeraar, pensioenfonds of andere partij die hypothecair krediet of ander krediet verstrekt. Elke geldverstrekker hanteert eigen acceptatievoorwaarden binnen de wettelijke leennormen.`,zoek:['geldverstrekker','geldverstrekkers','hypotheekverstrekker','aanbieder hypotheek']},
 {term:'Gemeenschap van goederen',uitleg:`Huwelijksvermogensregime waarbij in principe alle bezittingen en schulden van beide echtgenoten gemeenschappelijk zijn. Was tot 2018 het wettelijke uitgangspunt en geldt nog voor eerder gesloten huwelijken zonder huwelijkse voorwaarden.`,zoek:['gemeenschap van goederen','algehele gemeenschap','algehele gemeenschap van goederen']},
 {term:'Gemengde verzekering',uitleg:`Levensverzekering die zowel uitkeert bij overlijden tijdens de looptijd als bij in leven zijn op de einddatum. Combineert risicodekking en vermogensopbouw.`,zoek:['gemengde verzekering','gemengde levensverzekering']},
 {term:'Geregistreerd partnerschap',uitleg:`Bij de burgerlijke stand geregistreerde samenlevingsvorm met grotendeels dezelfde rechtsgevolgen als een huwelijk, onder meer voor vermogen, erfrecht en alimentatie. Kan in bepaalde gevallen zonder rechter worden beëindigd.`,zoek:['geregistreerd partnerschap','partnerschapsvoorwaarden','geregistreerd partner']},
 {term:'Gewogen rente',uitleg:`Gemiddelde rente over meerdere leningdelen, gewogen naar de omvang van elk leningdeel. Wordt gebruikt bij rentemiddeling, oversluiten en het vergelijken van hypotheekaanbiedingen.`,zoek:['gewogen rente','gewogen gemiddelde rente']},
 {term:'Gezondheidsverklaring',uitleg:`Vragenlijst over de gezondheid die een verzekeraar gebruikt bij de acceptatie van een levens- of arbeidsongeschiktheidsverzekering. Onjuiste of onvolledige antwoorden kunnen gevolgen hebben voor de uitkering.`,zoek:['gezondheidsverklaring','medische vragenlijst','medische acceptatie','medische keuring']},
 {term:'Glasverzekering',uitleg:`Verzekering of dekking voor breuk van ruiten en ander glas in een woning of bedrijfspand. Vaak meeverzekerd op de opstal- of inboedelverzekering.`,zoek:['glasverzekering','glasdekking','glasschade']},
 {term:'Groene beleggingen',uitleg:`Beleggingen in door de overheid aangewezen groene fondsen of projecten. Hiervoor geldt in box 3 een vrijstelling tot een maximumbedrag; de fiscale voordelen worden de laatste jaren beperkt.`,zoek:['groene beleggingen','groen beleggen','groenfonds']},
 {term:'HDN (Hypotheken Data Netwerk)',uitleg:`Netwerk en berichtenstandaard waarmee adviseurs en geldverstrekkers hypotheekaanvragen, offertes en statusberichten digitaal uitwisselen. Veel adviessoftware verstuurt aanvragen via HDN.`,zoek:['hdn','hdn-bericht','hdn-aanvraag','hypotheken data netwerk']},
 {term:'Heffingsvrij vermogen',uitleg:`Deel van de rendementsgrondslag in box 3 waarover geen belasting wordt geheven. Fiscale partners kunnen het heffingsvrij vermogen samen benutten.`,zoek:['heffingsvrij vermogen','heffingvrij vermogen','vrijstelling box 3']},
 {term:'Herbouwwaarde',uitleg:`Bedrag dat nodig is om een woning na volledige verwoesting op dezelfde plek in dezelfde staat te herbouwen. Grondslag voor de opstalverzekering en los van de marktwaarde.`,zoek:['herbouwwaarde','herbouwkosten']},
 {term:'Herverzekering',uitleg:`Verzekering van een verzekeraar bij een andere verzekeraar om grote risico's te spreiden. Voor de klant meestal niet zichtbaar, maar van belang voor de solvabiliteit van de verzekeraar.`,zoek:['herverzekering','herverzekeraar']},
 {term:'Holding',uitleg:`Vennootschap die aandelen houdt in een of meer andere vennootschappen, vaak de werkmaatschappij van een DGA. Wordt gebruikt om risico's te scheiden en winst fiscaal gunstig door te schuiven.`,zoek:['holding','holding-bv','holdingstructuur']},
 {term:'Hoofdelijke aansprakelijkheid',uitleg:`Situatie waarin iedere schuldenaar tegenover de schuldeiser voor het volledige bedrag van de schuld kan worden aangesproken. Bij een gezamenlijke hypotheek zijn beide partners doorgaans hoofdelijk aansprakelijk, ook na een scheiding totdat ontslag uit hoofdelijkheid is verleend.`,zoek:['hoofdelijk aansprakelijk','hoofdelijke aansprakelijkheid','hoofdelijkheid','ontslag uit hoofdelijkheid']},
 {term:'Hoofdsom',uitleg:`Het oorspronkelijk geleende bedrag van een lening, exclusief rente en kosten. Over de openstaande hoofdsom wordt rente berekend.`,zoek:['hoofdsom','leningsbedrag','restant hoofdsom']},
 {term:'Hoofdverblijf',uitleg:`Woning die de belastingplichtige niet slechts tijdelijk als hoofdverblijf ter beschikking staat. Dit is een kernvoorwaarde voor de fiscale eigen woning en daarmee voor hypotheekrenteaftrek.`,zoek:['hoofdverblijf']},
 {term:'Hoog-laagconstructie',uitleg:`Keuze om het ouderdomspensioen de eerste jaren hoger en daarna lager te laten uitkeren. Fiscaal geldt een maximale verhouding tussen de hoge en de lage uitkering.`,zoek:['hoog-laagconstructie','hoog-laag','hoog laag pensioen']},
 {term:'Huurbescherming',uitleg:`Wettelijke bescherming van huurders tegen opzegging en ongerechtvaardigde huurverhoging. Verhuurde woningen met huurbescherming hebben in de regel een lagere waarde in verhuurde staat dan de vrije marktwaarde.`,zoek:['huurbescherming','huurdersbescherming']},
 {term:'Huwelijkse voorwaarden',uitleg:`Notariële akte waarin echtgenoten afwijken van het wettelijke huwelijksvermogensregime, bijvoorbeeld door uitsluiting van iedere gemeenschap met of zonder verrekenbeding. Bepalen mede wie eigenaar is van de woning en hoe schulden worden verdeeld.`,zoek:['huwelijkse voorwaarden','huwelijksvoorwaarden','huwelijksvermogensrecht','huwelijksgoederenrecht']},
 {term:'Hypothecaire inschrijving',uitleg:`Inschrijving van het recht van hypotheek in de openbare registers van het Kadaster, waarmee de geldverstrekker zekerheid krijgt op de woning. Het ingeschreven bedrag kan hoger zijn dan de lening, zodat later zonder nieuwe akte kan worden bijgeleend.`,zoek:['hypothecaire inschrijving','recht van hypotheek','hypotheekrecht']},
 {term:'Hypotheekakte',uitleg:`Notariële akte waarin het recht van hypotheek wordt gevestigd ten gunste van de geldverstrekker. De akte wordt bij het passeren ondertekend en ingeschreven in het Kadaster.`,zoek:['hypotheekakte','hypotheekaktes']},
 {term:"Hypotheekcijfer",uitleg:`Betaalbaarheidscheck van de Nationale Hypotheekbond die geldverstrekkers hun klanten laten doen: een cijfer en rapport over of de hypotheek nu en later betaalbaar blijft. Zie k320.`,zoek:['hypotheekcijfer','hypotheekcijfer.nl']},
 {term:'Hypotheekgever',uitleg:`De schuldenaar die zijn woning tot zekerheid aan de geldverstrekker geeft. De geldverstrekker is de hypotheekhouder of hypotheeknemer.`,zoek:['hypotheekgever','hypotheekhouder','hypotheeknemer']},
 {term:'Hypotheekrenteaftrek',uitleg:`Fiscale aftrek in box 1 van betaalde rente op de eigenwoningschuld. Het tarief waartegen de rente aftrekbaar is, is beperkt en voor schulden vanaf 2013 gelden aanvullende voorwaarden zoals de aflossingseis.`,zoek:['hypotheekrenteaftrek','renteaftrek','aftrek hypotheekrente']},
 {term:'IB-ondernemer',uitleg:`Ondernemer die inkomstenbelasting betaalt over de winst uit zijn onderneming, zoals een eenmanszaak of vennoot in een vof. Bij een hypotheekaanvraag wordt het inkomen meestal vastgesteld via een inkomensverklaring op basis van meerdere jaarcijfers.`,zoek:['ib-ondernemer','eenmanszaak','vof','winst uit onderneming']},
 {term:'IBL (Inkomensbepaling Loondienst)',uitleg:`Methode waarbij het toetsinkomen van een werknemer wordt bepaald op basis van gegevens uit de polisadministratie van het UWV, in plaats van uitsluitend een werkgeversverklaring. Hiermee kan onder voorwaarden ook inkomen bij een tijdelijk contract of flexibele uren worden meegenomen.`,zoek:['ibl','inkomensbepaling loondienst','ibl-toets','ibl-tool']},
 {term:'IDD (Insurance Distribution Directive)',uitleg:`Europese richtlijn over de distributie van verzekeringen, met eisen aan onder meer productontwikkeling, informatieverstrekking, belangenconflicten en vakbekwaamheid. In Nederland geïmplementeerd in de Wft en onderliggende regelgeving.`,zoek:['idd','insurance distribution directive','verzekeringsdistributierichtlijn']},
 {term:'iDIN',uitleg:`Identificatiemiddel waarmee consumenten zich online legitimeren via de inlogomgeving van hun eigen bank. Wordt gebruikt voor digitaal cliëntenonderzoek en ondertekenen.`,zoek:['idin','bankid']},
 {term:'Inboedelverzekering',uitleg:`Schadeverzekering die de spullen in de woning dekt tegen gebeurtenissen zoals brand, diefstal en waterschade. De verzekerde som en eventuele onderverzekering zijn belangrijke aandachtspunten.`,zoek:['inboedelverzekering','inboedelverzekeringen','inboedel']},
 {term:'Indexatie',uitleg:`Aanpassing van pensioenaanspraken of uitkeringen aan prijs- of loonontwikkeling, ook wel toeslagverlening. Of indexatie plaatsvindt hangt af van de regeling en de financiële positie van het fonds.`,zoek:['indexatie','toeslagverlening','indexeren']},
 {term:'Indexclausule',uitleg:`Bepaling in een schadeverzekering waarmee het verzekerde bedrag jaarlijks wordt aangepast aan prijsontwikkelingen. Helpt onderverzekering te voorkomen.`,zoek:['indexclausule','indexering verzekerd bedrag']},
 {term:'Inhaalruimte',uitleg:`Ruimte om onbenutte jaarruimte uit voorgaande jaren alsnog te gebruiken voor aftrekbare lijfrentepremies. Er kan worden teruggekeken over een beperkt aantal jaren en het bedrag per jaar is gemaximeerd. Ook wel reserveringsruimte genoemd.`,zoek:['inhaalruimte','reserveringsruimte']},
 {term:'Inkomensverklaring ondernemer',uitleg:`Verklaring van een gecertificeerde rekenexpert over het duurzaam te verwachten inkomen van een zelfstandige, op basis van de jaarcijfers. Geldverstrekkers gebruiken deze verklaring om het toetsinkomen van ondernemers vast te stellen.`,zoek:['inkomensverklaring','inkomensverklaring ondernemer','ivo']},
 {term:'Inkomstenbelasting',uitleg:`Belasting over het inkomen van natuurlijke personen, verdeeld over box 1 (werk en woning), box 2 (aanmerkelijk belang) en box 3 (sparen en beleggen). Loonheffing en voorlopige aanslagen zijn voorheffingen op deze belasting.`,zoek:['inkomstenbelasting','ib','aangifte inkomstenbelasting','ib-aangifte']},
 {term:'Interne klachtenprocedure',uitleg:`Verplichte procedure binnen een financiële onderneming om klachten van klanten zorgvuldig en tijdig af te handelen. Komt men er niet uit, dan kan de klant naar het Kifid.`,zoek:['klachtenprocedure','klachtenregeling','interne klachtenprocedure','klachtafhandeling']},
 {term:'IVA (Inkomensvoorziening Volledig Arbeidsongeschikten)',uitleg:`WIA-uitkering voor werknemers die volledig en duurzaam arbeidsongeschikt zijn. De uitkering loopt in principe door tot de AOW-leeftijd.`,zoek:['iva','inkomensvoorziening volledig arbeidsongeschikten']},
 {term:'Jaaropgaaf',uitleg:`Overzicht dat een geldverstrekker of verzekeraar jaarlijks verstrekt met onder meer de betaalde rente, de stand van de schuld of de waarde van een polis. Wordt gebruikt voor de aangifte inkomstenbelasting.`,zoek:['jaaropgaaf','jaaropgave','jaaropgaven']},
 {term:'Jaarruimte',uitleg:`Ruimte om in een jaar fiscaal aftrekbaar premie te betalen voor een lijfrente bij een pensioentekort. De jaarruimte wordt berekend op basis van de premiegrondslag en de pensioenaangroei van het voorgaande jaar.`,zoek:['jaarruimte','jaarruimteberekening']},
 {term:'JKP (jaarlijks kostenpercentage)',uitleg:`Percentage dat de totale kosten van een krediet voor de consument per jaar uitdrukt, inclusief rente en bepaalde bijkomende kosten. Maakt aanbiedingen van hypotheken en consumptieve kredieten onderling vergelijkbaar.`,zoek:['jkp','jaarlijks kostenpercentage','effectieve rente']},
 {term:'Kadaster',uitleg:`Dienst die de openbare registers bijhoudt van onroerende zaken, zoals eigendom, hypotheken en beperkte rechten. Inschrijving in het Kadaster is nodig voor de eigendomsoverdracht en voor het hypotheekrecht.`,zoek:['kadaster','kadastraal','kadastrale gegevens','eigendomsinformatie']},
 {term:'Kapitaalmarktrente',uitleg:`Rente op langlopende leningen en obligaties, die mede bepalend is voor de hypotheekrente bij langere rentevaste perioden. Veranderingen in de kapitaalmarktrente werken meestal met enige vertraging door in de tarieven.`,zoek:['kapitaalmarktrente','obligatierente','staatsobligatie']},
 {term:'Kapitaalverzekering',uitleg:`Levensverzekering die op een vastgestelde datum of bij overlijden een kapitaal uitkeert. Werd veel gebruikt voor aflossing van de hypotheek; als KEW kon deze onder overgangsrecht fiscaal vrijgesteld zijn.`,zoek:['kapitaalverzekering','kapitaalverzekeringen']},
 {term:'Kerstarrest',uitleg:`Uitspraak van de Hoge Raad van 24 december 2021 waarin het box 3-stelsel op basis van forfaitaire rendementen in strijd werd geacht met het eigendomsrecht en het discriminatieverbod. Leidde tot rechtsherstel en een herziening van box 3.`,zoek:['kerstarrest','hoge raad box 3','rechtsherstel box 3']},
 {term:'KEW (kapitaalverzekering eigen woning)',uitleg:`Kapitaalverzekering die bestemd is voor aflossing van de eigenwoningschuld. Onder overgangsrecht kon de uitkering onder voorwaarden binnen een vrijstelling vallen.`,zoek:['kew','kapitaalverzekering eigen woning']},
 {term:'Kifid (Klachteninstituut Financiële Dienstverlening)',uitleg:`Onafhankelijk instituut voor de behandeling van klachten en geschillen tussen consumenten en financiële dienstverleners. Aansluiting bij een erkende geschilleninstantie is voor Wft-vergunninghouders die met consumenten werken verplicht.`,zoek:['kifid','klachteninstituut','klachteninstituut financiële dienstverlening']},
 {term:'Klantbelang centraal',uitleg:`Uitgangspunt dat financiële dienstverleners bij producten en advies het belang van de klant voorop stellen. De AFM toetst hierop via onder meer zorgplicht, productontwikkeling en beloningsregels.`,zoek:['klantbelang centraal','kbc','klantbelang voorop']},
 {term:'Klantdossier',uitleg:`Vastlegging van alle relevante informatie over een klant en de verleende dienst, zoals de inventarisatie, het klantprofiel, het advies en de communicatie. Nodig om te kunnen aantonen dat het advies passend was.`,zoek:['klantdossier','dossiervorming','adviesdossier','dossiervastlegging']},
 {term:'Klantinventarisatie',uitleg:`Verzamelen van gegevens over de financiële positie, kennis en ervaring, doelstellingen en risicobereidheid van de klant. Vormt de basis voor een passend advies en het klantprofiel.`,zoek:['inventarisatie','klantinventarisatie','inventarisatieformulier']},
 {term:'Klantprofiel',uitleg:`Vastlegging van de relevante gegevens van de klant, zoals financiële positie, kennis en ervaring, doelstellingen en risicobereidheid. Het klantprofiel vormt de basis voor een passend advies en moet in het dossier aantoonbaar zijn.`,zoek:['klantprofiel','klantprofielen','inventarisatie klant']},
 {term:"Klimaatcijfer",uitleg:`Klimaatrisico van een woning in één cijfer van 1 tot 10, uit fundering, overstroming, hitte, wateroverlast en droogte, met een bandbreedte. Een indicatie, geen actuarieel model. Zie k353.`,zoek:['klimaatcijfer','klimaatcijfer.nl']},
 {term:'Koop-/aanneemovereenkomst',uitleg:`Combinatie van een koopovereenkomst voor de grond en een aannemingsovereenkomst voor de bouw van een nieuwbouwwoning. De koper betaalt in termijnen naar bouwvoortgang, meestal via een bouwdepot.`,zoek:['koop-/aanneemovereenkomst','koopaanneemovereenkomst','koop- en aanneemovereenkomst','nieuwbouw']},
 {term:'Koopovereenkomst',uitleg:`Schriftelijke overeenkomst tussen koper en verkoper van een woning met prijs, leverdatum, ontbindende voorwaarden en waarborgsom. De datum van het financieringsvoorbehoud bepaalt hoeveel tijd er is voor de hypotheekaanvraag.`,zoek:['koopovereenkomst','koopakte','koopcontract','voorlopig koopcontract']},
 {term:'Koopsom',uitleg:`Eenmalige premie waarmee een verzekering of uitkering wordt aangekocht, zoals bij een direct ingaande lijfrente of een uitvaartverzekering.`,zoek:['koopsom','koopsompolis','eenmalige premie']},
 {term:'Kosten koper',uitleg:`Bijkomende kosten die bij aankoop van een bestaande woning voor rekening van de koper komen, zoals overdrachtsbelasting en notariskosten voor de leveringsakte. Deze kosten kunnen niet volledig worden meegefinancierd.`,zoek:['kosten koper','k.k.']},
 {term:'Koude uitsluiting',uitleg:`Huwelijkse voorwaarden waarbij iedere gemeenschap is uitgesloten en geen verrekenbeding is opgenomen. Bij scheiding of overlijden hoeft vermogen dan niet te worden gedeeld, wat aandacht vraagt bij de financiering van de gezamenlijke woning.`,zoek:['koude uitsluiting']},
 {term:'Krediethypotheek',uitleg:`Hypothecaire kredietfaciliteit waarbij de klant binnen een limiet kan opnemen en aflossen. Voor renteaftrek moet het opgenomen bedrag voor de eigen woning worden gebruikt en aan de aflossingseis voldoen.`,zoek:['krediethypotheek','hypothecair krediet met limiet']},
 {term:'Kredietlimiet',uitleg:`Maximaal op te nemen bedrag bij een doorlopend krediet, creditcard of roodstand. Bij de hypotheektoets telt doorgaans een percentage van de limiet mee als maandlast, ook als het krediet niet is opgenomen.`,zoek:['kredietlimiet','limiet','bestedingslimiet']},
 {term:'Kredietovereenkomst',uitleg:`Overeenkomst waarbij een kredietgever een consument krediet verleent. Voor consumptief krediet gelden in de Wft informatieplichten, een kredietwaardigheidstoets en een herroepingsrecht.`,zoek:['kredietovereenkomst','kredietcontract','herroepingsrecht krediet']},
 {term:'Kredietvergoeding',uitleg:`Totale vergoeding die de consument betaalt voor een krediet, zoals rente en kosten. Voor consumptief krediet geldt een wettelijk maximum dat is gekoppeld aan de wettelijke rente.`,zoek:['kredietvergoeding','maximale kredietvergoeding','kredietrente']},
 {term:'Kredietwaardigheidstoets',uitleg:`Beoordeling door de kredietverstrekker of de consument het krediet verantwoord kan dragen, op basis van inkomen, lasten en registraties. Bij hypothecair krediet zijn de leennormen uit de Trhk leidend.`,zoek:['kredietwaardigheid','kredietwaardigheidstoets','kredietwaardigheidsbeoordeling']},
 {term:'Kruislingse ORV',uitleg:`Overlijdensrisicoverzekering waarbij partners elkaars leven verzekeren en ieder de premie betaalt voor de polis op het leven van de ander. Hierdoor valt de uitkering bij overlijden doorgaans niet onder de erfbelasting.`,zoek:['kruislingse orv','kruislings verzekerd','kruislingse overlijdensrisicoverzekering']},
 {term:'Kwalitatieve verplichting',uitleg:`Verplichting die bij een notariële akte aan een onroerende zaak wordt gekoppeld en overgaat op volgende eigenaren, zoals een plicht om iets te dulden of na te laten. Ingeschreven in het Kadaster.`,zoek:['kwalitatieve verplichting']},
 {term:'Langstlevende',uitleg:`De partner die na het overlijden van de ander achterblijft. In het erfrecht en bij pensioen en ORV is de positie van de langstlevende een belangrijk aandachtspunt, bijvoorbeeld voor het kunnen blijven wonen.`,zoek:['langstlevende','langstlevendetestament','langstlevende partner']},
 {term:'Leegwaarderatio',uitleg:`Verhouding tussen de waarde van een woning in verhuurde staat en de waarde in onverhuurde staat. Wordt fiscaal gebruikt om verhuurde woningen met huurbescherming in box 3 te waarderen.`,zoek:['leegwaarderatio','waarde verhuurde staat','verhuurde staat']},
 {term:'Leennormen',uitleg:`Normen voor verantwoorde hypotheekverstrekking, met name de maximale financieringslast ten opzichte van het inkomen en de maximale lening ten opzichte van de woningwaarde. Ze zijn vastgelegd in de Trhk en worden periodiek geactualiseerd.`,zoek:['leennormen','leennorm','hypotheeknormen']},
 {term:'Legaat',uitleg:`Bepaling in een testament waarmee iemand een specifiek goed of geldbedrag krijgt zonder erfgenaam te worden. De legataris is niet aansprakelijk voor schulden van de nalatenschap.`,zoek:['legaat','legaten','legataris']},
 {term:'Legitieme portie',uitleg:`Wettelijk minimumdeel waarop een kind aanspraak kan maken, ook als het in het testament is onterfd. Het is een geldvordering op de erfgenamen en moet binnen een wettelijke termijn worden ingeroepen.`,zoek:['legitieme portie','legitimaris','legitieme']},
 {term:'Levenstestament',uitleg:`Notariële akte waarin iemand volmachten geeft voor financiële en medische beslissingen voor het geval hij zelf niet meer kan handelen. Kan onder meer regelen wie namens de klant over de woning, hypotheek en verzekeringen mag beslissen.`,zoek:['levenstestament','levens testament','notariële volmacht','volmacht levenstestament']},
 {term:'Lifecycle',uitleg:`Beleggingsmix in een premieregeling die automatisch defensiever wordt naarmate de pensioendatum nadert. Beperkt het risico dat een koersdaling vlak voor pensionering grote gevolgen heeft.`,zoek:['lifecycle','life cycle','lifecyclebeleggen']},
 {term:'Lijfrente',uitleg:`Periodieke uitkering, opgebouwd via een lijfrenteverzekering of lijfrenterekening, die dient als aanvulling op het pensioen of als nabestaanden- of arbeidsongeschiktheidsvoorziening. Premies zijn binnen de jaarruimte en reserveringsruimte aftrekbaar; uitkeringen worden belast in box 1.`,zoek:['lijfrente','lijfrenteverzekering','lijfrenterekening','lijfrentepremie']},
 {term:'Lineaire hypotheek',uitleg:`Hypotheekvorm waarbij elke maand een gelijk bedrag wordt afgelost, waardoor de bruto maandlast in het begin hoog is en daarna daalt. Voldoet bij volledige aflossing binnen 30 jaar aan de aflossingseis.`,zoek:['lineair','lineaire hypotheek','lineaire aflossing']},
 {term:'Loondoorbetaling bij ziekte',uitleg:`Verplichting van de werkgever om bij ziekte van een werknemer gedurende maximaal 104 weken een deel van het loon door te betalen. Daarna kan de werknemer een WIA-uitkering aanvragen.`,zoek:['loondoorbetaling','loondoorbetaling bij ziekte','104 weken']},
 {term:'Loonheffing',uitleg:`Verzamelnaam voor loonbelasting, premie volksverzekeringen en inkomensafhankelijke bijdrage Zvw die de werkgever inhoudt of betaalt. De loonbelasting is een voorheffing op de inkomstenbelasting.`,zoek:['loonheffing','loonheffingen','loonbelasting']},
 {term:'Looptijdrente',uitleg:`Gemiddelde rente die een klant naar verwachting betaalt over de hele looptijd van de hypotheek. Houdt rekening met automatische verlaging van de renteopslag zodra de lening door aflossing in een lagere risicoklasse (loan-to-value) valt. Vergelijken op looptijdrente kan via looptijdrente.nl.`,zoek:['looptijdrente','looptijdrente.nl','gemiddelde rente','risicoklasse']},
 {term:'LTI (loan-to-income)',uitleg:`Verhouding tussen de hoogte van de lening en het inkomen van de kredietnemer. In Nederland wordt deze begrenzing vormgegeven via de financieringslastpercentages.`,zoek:['lti','loan-to-income','loan to income']},
 {term:'LTV (loan-to-value)',uitleg:`Verhouding tussen de hoogte van de hypotheek en de marktwaarde van de woning. De LTV is begrensd door de leennormen en bepaalt bij veel geldverstrekkers de risico-opslag in de rente.`,zoek:['ltv','loan-to-value','loan to value']},
 {term:'Marktwaarde',uitleg:`Geschatte prijs die een woning op de taxatiedatum bij verkoop op de vrije markt zou opbrengen, vastgesteld door een gevalideerde taxatie. De marktwaarde, eventueel na verbouwing, is de basis voor de maximale lening op grond van de LTV-norm.`,zoek:['marktwaarde','vrije verkoopwaarde','marktwaarde na verbouwing']},
 {term:'Maximale hypotheek',uitleg:`Hoogste lening die volgens de leennormen verantwoord kan worden verstrekt, begrensd door zowel het inkomen als de waarde van de woning. Lopende verplichtingen zoals kredieten en studieschuld verlagen de maximale hypotheek.`,zoek:['maximale hypotheek','maximaal te lenen','leencapaciteit']},
 {term:'MCD (Hypothecair Kredietrichtlijn)',uitleg:`Europese richtlijn (Mortgage Credit Directive) met regels voor hypothecair krediet aan consumenten, zoals precontractuele informatie via het ESIS, het JKP en de beoordeling van de kredietwaardigheid. In Nederland verwerkt in de Wft en het Bgfo.`,zoek:['mcd','mortgage credit directive','hypothecair kredietrichtlijn']},
 {term:'Mede-eigendom',uitleg:`Situatie waarin twee of meer personen samen eigenaar zijn van een goed, zoals een woning, ieder voor een bepaald aandeel. Het eigendomsaandeel is fiscaal relevant voor de toerekening van de eigenwoningschuld en het eigenwoningforfait.`,zoek:['mede-eigendom','mede-eigenaar','eigendomsverhouding','eigendomsaandeel']},
 {term:'Mededelingsplicht',uitleg:`Wettelijke plicht van de aspirant-verzekeringnemer om voor het sluiten van een verzekering alle feiten te melden die hij kent of behoort te kennen en die voor de verzekeraar van belang zijn. Schending kan leiden tot beperking of weigering van de uitkering.`,zoek:['mededelingsplicht','precontractuele mededelingsplicht','verzwijging']},
 {term:'MiFID II',uitleg:`Europese richtlijn met regels voor beleggingsdienstverlening, onder meer over passendheid, geschiktheid, kostentransparantie en productgovernance. Relevant voor adviseurs die beleggingsadvies geven of bemiddelen in beleggingsproducten.`,zoek:['mifid','mifid ii','mifid 2']},
 {term:'MJOP (meerjarenonderhoudsplan)',uitleg:`Planning van het groot onderhoud van een gebouw voor een reeks jaren, met de bijbehorende kosten. Voor een VvE de basis voor de jaarlijkse reservering in het reservefonds.`,zoek:['mjop','meerjarenonderhoudsplan','meerjaren onderhoudsplan']},
 {term:'MKB-winstvrijstelling',uitleg:`Vrijstelling van een percentage van de winst voor IB-ondernemers, berekend na aftrek van de ondernemersaftrek. Het urencriterium is hiervoor niet vereist.`,zoek:['mkb-winstvrijstelling','mkb winstvrijstelling']},
 {term:'Nabestaandenpensioen',uitleg:`Pensioen dat na overlijden van de deelnemer wordt uitgekeerd aan de partner (partnerpensioen) en/of kinderen (wezenpensioen). De dekking verschilt per regeling, bijvoorbeeld op opbouwbasis of risicobasis.`,zoek:['nabestaandenpensioen','partnerpensioen','wezenpensioen']},
 {term:'Nationaal Warmtefonds',uitleg:`Stichting die met steun van de overheid leningen verstrekt voor energiebesparende maatregelen aan woningeigenaren en VvE's, zoals isolatie en warmtepompen. Een lening van het fonds kan naast of in plaats van extra hypotheek worden ingezet.`,zoek:['warmtefonds','nationaal warmtefonds','energiebespaarlening']},
 {term:'Nazorg',uitleg:`Dienstverlening na het afsluiten van een product, zoals het periodiek controleren of de oplossing nog past bij de situatie van de klant. Afspraken over nazorg horen duidelijk in de dienstverleningsovereenkomst te staan.`,zoek:['nazorg','onderhoudsabonnement','periodieke evaluatie','service-abonnement']},
 {term:'Netto maandlast',uitleg:`Maandlast van de hypotheek na verrekening van het fiscale voordeel van de renteaftrek en eventuele andere fiscale effecten. Wordt in adviesrapporten naast de bruto maandlast gepresenteerd.`,zoek:['netto maandlast','netto maandlasten','netto woonlasten']},
 {term:'Nettopensioen',uitleg:`Vrijwillige pensioenregeling voor het deel van het salaris boven de fiscale maximumgrens van het pensioengevend loon. De premie is niet aftrekbaar, maar de aanspraak is vrijgesteld in box 3 en de uitkering is onbelast.`,zoek:['nettopensioen','netto pensioen','nettolijfrente']},
 {term:'NHG (Nationale Hypotheek Garantie)',uitleg:`Garantie van de Stichting Waarborgfonds Eigen Woningen die geldverstrekkers zekerheid geeft en de consument onder voorwaarden beschermt tegen een restschuld na gedwongen verkoop. Een hypotheek met NHG kent doorgaans een lagere rente; of NHG mogelijk is, hangt onder meer af van de NHG-grens (2026: € 470.000, of € 498.200 met energiebesparende voorzieningen), die jaarlijks wordt vastgesteld.`,zoek:['nhg','nationale hypotheek garantie','nhg-grens','kostengrens nhg','waarborgfonds eigen woningen']},
 {term:'NHG-grens',uitleg:`Grens die bepaalt of een hypotheek met Nationale Hypotheek Garantie mogelijk is. NHG toetst er zowel de kosten van de woning (ook als de klant een deel zelf betaalt) als de hoogte van de lening aan. In 2026 is de NHG-grens € 470.000, of € 498.200 als er ook wordt geleend voor energiebesparende voorzieningen (maximaal € 28.200 extra). Sinds 2026 geldt één grens voor alle woningtypen. De grens wordt jaarlijks vastgesteld; gebruik het bedrag dat geldt voor het jaar van het bindend aanbod. Tot 2024 heette dit de kostengrens.`,zoek:['nhg-grens','nhg grens','kostengrens','kostengrens nhg','nhg-kostengrens','grens nhg']},
 {term:'NHT (Nederlandse Herverzekeringsmaatschappij voor Terrorismeschaden)',uitleg:`Herverzekeraar waarbij Nederlandse verzekeraars terrorismerisico's onderbrengen. Polissen bevatten een clausule die de uitkering bij terrorismeschade begrenst.`,zoek:['nht','terrorismeschade','terrorismeclausule']},
 {term:'Nibud (Nationaal Instituut voor Budgetvoorlichting)',uitleg:`Onafhankelijke stichting die onderzoek doet naar huishoudbudgetten. Het Nibud adviseert jaarlijks over de financieringslastpercentages die de basis vormen voor de leennormen.`,zoek:['nibud','nationaal instituut voor budgetvoorlichting','nibud-normen']},
 {term:'Nieuwwaarde',uitleg:`Bedrag dat nodig is om een beschadigde of verloren zaak te vervangen door een nieuwe zaak van dezelfde soort en kwaliteit. Veel inboedelpolissen vergoeden op nieuwwaardebasis, met uitzonderingen voor oudere of minder waardevolle spullen.`,zoek:['nieuwwaarde','nieuwwaarderegeling','nieuwwaardevergoeding']},
 {term:'Nota van afrekening',uitleg:`Overzicht van de notaris waarin alle bedragen bij de overdracht en het passeren van de hypotheek worden verrekend. Hieruit blijkt onder meer welk bedrag de koper zelf moet inbrengen.`,zoek:['nota van afrekening','afrekening notaris']},
 {term:'Notaris',uitleg:`Onafhankelijke jurist die onder meer de akte van levering en de hypotheekakte opstelt en passeert, de geldstromen via de derdengeldenrekening afwikkelt en zorgt voor inschrijving in het Kadaster. Stelt ook testamenten, huwelijkse voorwaarden en samenlevingscontracten op.`,zoek:['notaris','notarissen','notariskosten','notariële akte']},
 {term:'NRVT (Nederlands Register Vastgoed Taxateurs)',uitleg:`Register waarin vastgoedtaxateurs zijn ingeschreven die aan opleidings- en kwaliteitseisen voldoen. Geldverstrekkers accepteren taxatierapporten van geregistreerde taxateurs.`,zoek:['nrvt','register vastgoed taxateurs','register-taxateur']},
 {term:'NWWI (Nederlands Woningwaarde Instituut)',uitleg:`Validatie-instituut dat taxatierapporten van woningen controleert op volledigheid en plausibiliteit voordat geldverstrekkers ze gebruiken. Werkt met gecertificeerde taxateurs.`,zoek:['nwwi','nederlands woningwaarde instituut','taxatievalidatie','validatie-instituut']},
 {term:'Ockto',uitleg:`App waarmee consumenten met DigiD hun financiële gegevens, zoals inkomen, pensioen en woninggegevens, ophalen bij overheidsbronnen en delen met hun adviseur. Vermindert handmatig verzamelen van documenten en fouten.`,zoek:['ockto','gegevens ophalen','dataverzameling']},
 {term:'Offerte (hypotheekofferte)',uitleg:`Aanbod van de geldverstrekker met de voorwaarden van de hypotheek, zoals rente, rentevaste periode en geldigheidsduur. Na ondertekening en akkoord op de voorwaarden kan de hypotheek bij de notaris passeren.`,zoek:['hypotheekofferte','offerte','bindend aanbod','offertetermijn']},
 {term:'Onafhankelijk adviseur',uitleg:`Aanduiding die een financiële dienstverlener volgens de Wft alleen mag gebruiken als het advies is gebaseerd op een analyse van een toereikend aantal producten en hij geen provisie van aanbieders ontvangt voor de betreffende dienstverlening.`,zoek:['onafhankelijk adviseur','onafhankelijk advies','onafhankelijkheid']},
 {term:'Onderbewindstelling',uitleg:`Maatregel van de kantonrechter waarbij een bewindvoerder het vermogen van een persoon beheert, bijvoorbeeld bij problematische schulden of beperkte handelingsbekwaamheid. Voor het afsluiten van een hypotheek of krediet is dan medewerking van de bewindvoerder nodig.`,zoek:['bewind','bewindvoering','onderbewindstelling','curatele','mentorschap']},
 {term:'Ondernemersaftrek',uitleg:`Verzamelnaam voor fiscale aftrekposten voor IB-ondernemers, zoals de zelfstandigenaftrek, startersaftrek, meewerkaftrek en stakingsaftrek. De meeste posten vereisen dat aan het urencriterium wordt voldaan.`,zoek:['ondernemersaftrek','startersaftrek','meewerkaftrek','stakingsaftrek']},
 {term:'Onderverzekering',uitleg:`Situatie waarin het verzekerde bedrag lager is dan de werkelijke waarde van het verzekerde object. Bij schade kan de verzekeraar dan naar evenredigheid uitkeren.`,zoek:['onderverzekering','onderverzekerd','evenredigheidsregel']},
 {term:'Ongevallenverzekering',uitleg:`Verzekering die een vast bedrag uitkeert bij overlijden of blijvende invaliditeit door een ongeval. Dekt geen arbeidsongeschiktheid door ziekte.`,zoek:['ongevallenverzekering','ongevallen','invaliditeit']},
 {term:'Ontbindende voorwaarde financiering',uitleg:`Bepaling in de koopovereenkomst die de koper het recht geeft de koop te ontbinden als binnen de afgesproken termijn geen passende financiering wordt verkregen. Ook wel financieringsvoorbehoud genoemd.`,zoek:['ontbindende voorwaarde','financieringsvoorbehoud','voorbehoud van financiering']},
 {term:'Opbouwpercentage',uitleg:`Percentage van de pensioengrondslag dat in een uitkeringsregeling jaarlijks aan pensioen wordt opgebouwd. Fiscaal is het opbouwpercentage gemaximeerd.`,zoek:['opbouwpercentage','pensioenopbouw']},
 {term:'Opstalrecht',uitleg:`Zakelijk recht om in, op of boven de grond van een ander gebouwen of werken te hebben, zoals een woning of zonnepanelen. Komt vaak samen met erfpacht voor.`,zoek:['opstalrecht','recht van opstal']},
 {term:'Opstalverzekering',uitleg:`Schadeverzekering voor de woning zelf, inclusief vaste onderdelen, tegen gebeurtenissen zoals brand, storm en waterschade. Geldverstrekkers stellen een opstalverzekering doorgaans verplicht.`,zoek:['opstalverzekering','opstalverzekeringen','woonhuisverzekering']},
 {term:'ORV (overlijdensrisicoverzekering)',uitleg:`Verzekering die bij overlijden van de verzekerde binnen de looptijd een vooraf bepaald bedrag uitkeert. Wordt vaak gebruikt om de hypotheek bij overlijden (deels) af te lossen; kan gelijkblijvend, annuïtair of lineair dalend zijn.`,zoek:['orv','overlijdensrisicoverzekering','overlijdensrisicoverzekeringen']},
 {term:'Oudedagsverplichting (ODV)',uitleg:`Verplichting tot het doen van oudedagsuitkeringen die ontstond bij het omzetten van pensioen in eigen beheer. Wordt opgebouwd en uitgekeerd volgens de fiscale regels voor die regeling.`,zoek:['oudedagsverplichting','odv']},
 {term:'Ouderdomspensioen',uitleg:`Pensioen dat vanaf de pensioendatum levenslang wordt uitgekeerd aan de deelnemer, als aanvulling op de AOW. Opgebouwd via de werkgever, een beroepspensioenregeling of een eigen voorziening.`,zoek:['ouderdomspensioen','ouderdomspensioenen']},
 {term:'Overbieden',uitleg:`Bieden boven de vraagprijs of boven de verwachte marktwaarde van een woning. Omdat de lening is begrensd tot de marktwaarde volgens de taxatie, moet het verschil met eigen geld worden betaald.`,zoek:['overbieden','overbieding','overboden']},
 {term:'Overbruggingskrediet',uitleg:`Tijdelijke lening om de overwaarde van de huidige woning vrij te maken voor de aankoop van een nieuwe woning, zolang de oude woning nog niet is verkocht of geleverd. De rente kan onder voorwaarden fiscaal aftrekbaar zijn.`,zoek:['overbruggingskrediet','overbruggingslening','overbrugging']},
 {term:'Overdrachtsbelasting',uitleg:`Belasting die de koper verschuldigd is bij verkrijging van onroerend goed, berekend over de koopsom of hogere waarde. Voor de eigen woning gelden andere tarieven dan voor beleggingspanden, en onder voorwaarden een startersvrijstelling.`,zoek:['overdrachtsbelasting','overdrachtsbelasting woning']},
 {term:'Overgangsrecht',uitleg:`Fiscale regels die bestaande situaties beschermen bij wetswijzigingen, zoals eigenwoningschulden en KEW, SEW of BEW die op 31 december 2012 al bestonden. Onder overgangsrecht blijft rente onder voorwaarden aftrekbaar zonder aflossingseis.`,zoek:['overgangsrecht','overgangsregeling','bestaande eigenwoningschuld','oud regime']},
 {term:'Oversluiten',uitleg:`Het vervangen van een bestaande hypotheek door een nieuwe, bij dezelfde of een andere geldverstrekker, bijvoorbeeld voor een lagere rente of andere voorwaarden. Bij oversluiten binnen de rentevaste periode kan een vergoeding vervroegde aflossing verschuldigd zijn.`,zoek:['oversluiten','hypotheek oversluiten','oversluiting']},
 {term:'Oververzekering',uitleg:`Situatie waarin het verzekerde bedrag hoger is dan de werkelijke waarde van het verzekerde object. De verzekeraar vergoedt niet meer dan de werkelijke schade, zodat er onnodig premie wordt betaald.`,zoek:['oververzekering','oververzekerd']},
 {term:'Overwaarde',uitleg:`Verschil tussen de marktwaarde van de woning en de openstaande hypotheekschuld. Bij verkoop speelt de overwaarde een rol bij de eigenwoningreserve en de bijleenregeling.`,zoek:['overwaarde']},
 {term:'Pakketpolis',uitleg:`Combinatie van meerdere verzekeringen bij één verzekeraar onder één polis, zoals inboedel, opstal, aansprakelijkheid en auto. Biedt vaak pakketkorting en één aanspreekpunt.`,zoek:['pakketpolis','pakketverzekering','combinatiepolis']},
 {term:"PandWise",uitleg:`Woningdossier in de browser dat advertentiegegevens naast openbare registers (BAG, BRK, CBS, WOZ) zet, met signalen, buurtcijfers en een bied- en verkoopstrategie. Geen taxatie. Zie k351.`,zoek:['pandwise','woningdossier']},
 {term:'PARP (productgoedkeurings- en reviewproces)',uitleg:`Verplicht proces waarmee aanbieders en ontwikkelaars van financiële producten nagaan of een product evenwichtig rekening houdt met de belangen van de doelgroep, voordat het op de markt komt en periodiek daarna.`,zoek:['parp','productgoedkeuringsproces','product approval','productontwikkeling','pog']},
 {term:'Participatiewet',uitleg:`Wet die de bijstand regelt als vangnet voor mensen zonder voldoende inkomen of vermogen, en ondersteuning bij het vinden van werk. Uitgevoerd door gemeenten.`,zoek:['participatiewet','bijstand','bijstandsuitkering']},
 {term:'Passend advies',uitleg:`Advies dat aansluit bij de financiële positie, kennis en ervaring, doelstellingen en risicobereidheid van de klant, zoals de Wft vereist. De adviseur moet de onderbouwing in het dossier vastleggen.`,zoek:['passend advies','passendheid','adviesplicht']},
 {term:'Passende arbeid',uitleg:`Criterium bij arbeidsongeschiktheid waarbij wordt gekeken naar werk dat aansluit bij opleiding, ervaring en capaciteiten van de verzekerde. Ligt qua dekking tussen beroepsarbeidsongeschiktheid en gangbare arbeid.`,zoek:['passende arbeid','passende-arbeid']},
 {term:'PE (permanente educatie)',uitleg:`Verplichting voor Wft-adviseurs om hun vakbekwaamheid actueel te houden, onder meer via periodieke PE-examens. Zonder geldige PE mag de adviseur niet langer adviseren in het betreffende domein.`,zoek:['permanente educatie','pe-examen','pe-punten','pe-verplichting']},
 {term:'Peildatum box 3',uitleg:`De datum, 1 januari van het belastingjaar, waarop bezittingen en schulden voor box 3 worden gewaardeerd. Verschuivingen van vermogen rondom die datum kunnen door antiarbitragebepalingen worden gecorrigeerd.`,zoek:['peildatum','1 januari box 3']},
 {term:'Pensioen in eigen beheer',uitleg:`Pensioen dat een DGA in zijn eigen BV opbouwde. Opbouw is sinds 2017 niet meer mogelijk; bestaande aanspraken konden worden afgekocht, omgezet in een oudedagsverplichting of in eigen beheer blijven staan.`,zoek:['pensioen in eigen beheer','peb','eigenbeheerpensioen']},
 {term:'Pensioenfonds',uitleg:`Stichting die collectief de pensioenregeling uitvoert voor een bedrijfstak, beroepsgroep of onderneming. Staat onder toezicht van DNB en de AFM.`,zoek:['pensioenfonds','pensioenfondsen','bedrijfstakpensioenfonds']},
 {term:'Pensioengevend salaris',uitleg:`Deel van het loon dat volgens het pensioenreglement meetelt voor de pensioenopbouw. Bonussen en overwerk tellen niet altijd mee.`,zoek:['pensioengevend salaris','pensioengevend loon','pensioengevend inkomen']},
 {term:'Pensioenregister',uitleg:`Landelijke database waarin opgebouwde pensioenaanspraken bij pensioenuitvoerders en de AOW zijn opgenomen. Consumenten bekijken hun totaaloverzicht via mijnpensioenoverzicht.nl.`,zoek:['pensioenregister','mijnpensioenoverzicht','mijnpensioenoverzicht.nl']},
 {term:'Pensioenreglement',uitleg:`Document waarin de afspraken van een pensioenregeling staan, zoals de opbouw, nabestaandendekking, keuzemogelijkheden en premie. Basis voor het beoordelen van de pensioenpositie van een klant.`,zoek:['pensioenreglement','pensioenregeling','pensioenovereenkomst']},
 {term:'Pensioenrichtleeftijd',uitleg:`Leeftijd waarop het pensioen in een regeling standaard ingaat, gebruikt voor de berekening van de opbouw. De deelnemer kan het pensioen vaak eerder of later laten ingaan.`,zoek:['pensioenrichtleeftijd','pensioendatum','pensioeningangsdatum']},
 {term:'Pensioentekort',uitleg:`Verschil tussen het verwachte inkomen na pensionering en het gewenste inkomen. Kan worden aangevuld met lijfrente, vermogen in box 3, aflossing van de hypotheek of langer doorwerken.`,zoek:['pensioentekort','pensioengat','pensioentekort berekenen']},
 {term:'Pensioenverevening',uitleg:`Verdeling bij scheiding van het ouderdomspensioen dat tijdens het huwelijk of geregistreerd partnerschap is opgebouwd. Standaard krijgt de ex-partner de helft, tenzij partners iets anders afspreken.`,zoek:['pensioenverevening','verevening','wet pensioenverdeling bij scheiding','pensioenverdeling']},
 {term:'Pensioenwet',uitleg:`Wet die de verhouding regelt tussen werkgever, werknemer en pensioenuitvoerder, met onder meer eisen aan informatieverstrekking en financiering. Is door de Wtp ingrijpend gewijzigd.`,zoek:['pensioenwet','pw']},
 {term:'PEP (politiek prominent persoon)',uitleg:`Persoon met een prominente publieke functie, of een familielid of naaste geassocieerde daarvan. Op grond van de Wwft geldt bij PEP's verscherpt cliëntenonderzoek.`,zoek:['pep','politiek prominent persoon','politically exposed person']},
 {term:'Persoonlijke lening',uitleg:`Consumptief krediet met een vast bedrag, vaste looptijd en vaste rente, dat in termijnen wordt terugbetaald. Telt mee bij de bepaling van de maximale hypotheek.`,zoek:['persoonlijke lening','persoonlijke leningen']},
 {term:'Perspectiefverklaring',uitleg:`Verklaring van een daartoe erkende partij over het te verwachten toekomstige inkomen van een flexwerker of werknemer met een tijdelijk contract zonder intentieverklaring, op basis van onder meer werkhistorie en arbeidsmarktgegevens. Geldverstrekkers kunnen dit inkomen onder voorwaarden als toetsinkomen accepteren.`,zoek:['perspectiefverklaring','perspectiefverklaringen']},
 {term:'Polisvoorwaarden',uitleg:`Algemene en bijzondere voorwaarden die de dekking, uitsluitingen, verplichtingen en schaderegeling van een verzekering bepalen. Bij advies en vergelijking zijn deze leidend, niet alleen de premie.`,zoek:['polisvoorwaarden','verzekeringsvoorwaarden','algemene voorwaarden polis','bijzondere voorwaarden']},
 {term:'PPI (premiepensioeninstelling)',uitleg:`Pensioenuitvoerder die uitsluitend premieovereenkomsten uitvoert en geen verzekeringstechnische risico's draagt. Risicodekkingen worden bij een verzekeraar ondergebracht.`,zoek:['ppi','premiepensioeninstelling']},
 {term:'Precontractuele informatie',uitleg:`Informatie die de klant vóór het sluiten van een overeenkomst moet krijgen, zoals over de dienstverlening, kosten, product en risico's. Hiervoor worden onder meer de vergelijkingskaart (tot 1 april 2023 het dienstverleningsdocument), het ESIS en productinformatie gebruikt.`,zoek:['precontractuele informatie','informatieverstrekking','informatieplicht']},
 {term:'Premieovereenkomst',uitleg:`Pensioenregeling waarbij de premie vastligt en de hoogte van het uiteindelijke pensioen afhangt van rendement en inkoopmoment. Onder de Wtp worden pensioenregelingen premieovereenkomsten.`,zoek:['premieovereenkomst','premieregeling','dc-regeling']},
 {term:'Premievrijstelling bij arbeidsongeschiktheid',uitleg:`Dekking waarbij bij arbeidsongeschiktheid de premie of pensioenopbouw (deels) wordt voortgezet zonder dat de verzekerde of werkgever premie hoeft te betalen. Komt voor bij pensioenregelingen en levensverzekeringen.`,zoek:['premievrijstelling','pvao','premievrijstelling bij arbeidsongeschiktheid']},
 {term:'Private lease',uitleg:`Langlopend huurcontract voor een auto voor een vast maandbedrag, inclusief onderhoud en verzekering. Wordt bij het BKR geregistreerd en geldverstrekkers rekenen de leaselast mee bij de hypotheektoets.`,zoek:['private lease','privatelease','operational lease']},
 {term:'Protocol Verzekeringskeuringen',uitleg:`Gedragsregels van verzekeraars over medische keuringen, waaronder welke vragen mogen worden gesteld en tot welke vragengrens geen vragen over bepaalde erfelijke aandoeningen mogen worden gesteld.`,zoek:['protocol verzekeringskeuringen','keuringsprotocol','vragengrens']},
 {term:'Provisieverbod',uitleg:`Verbod voor adviseurs en bemiddelaars om provisie van aanbieders te ontvangen bij bepaalde complexe en impactvolle financiële producten, zoals hypothecair krediet en diverse levens- en arbeidsongeschiktheidsverzekeringen. De klant betaalt de adviseur rechtstreeks.`,zoek:['provisieverbod','provisie','adviesvergoeding']},
 {term:'Prudentieel toezicht',uitleg:`Toezicht op de financiële soliditeit van financiële instellingen, zoals buffers en risicobeheer, uitgevoerd door DNB. Onderscheidt zich van het gedragstoezicht van de AFM.`,zoek:['prudentieel toezicht','prudentieel','solvabiliteit']},
 {term:'PSD2 (Payment Services Directive 2)',uitleg:`Europese richtlijn voor betaaldiensten die het onder meer mogelijk maakt dat klanten met toestemming derden toegang geven tot hun betaalrekeninggegevens. Wordt gebruikt om bankafschriften en uitgaven digitaal te analyseren.`,zoek:['psd2','payment services directive','rekeninginformatiedienst']},
 {term:'Rangorde (hypotheek)',uitleg:`Volgorde waarin hypotheekrechten op hetzelfde onderpand zijn gevestigd. De eerste hypotheekhouder wordt bij verkoop of executie eerst voldaan; een tweede hypotheek heeft daardoor meer risico.`,zoek:['rangorde','eerste hypotheek','tweede hypotheek','eerste recht van hypotheek']},
 {term:'Rechtsbijstandverzekering',uitleg:`Verzekering die juridische hulp en kosten dekt bij geschillen, binnen de verzekerde rubrieken en voorwaarden. Wachttijden en uitsluitingen verschillen per aanbieder.`,zoek:['rechtsbijstandverzekering','rechtsbijstand']},
 {term:'Regresrecht',uitleg:`Recht van een hoofdelijk aansprakelijke schuldenaar die meer heeft betaald dan zijn deel, om het teveel betaalde te verhalen op de medeschuldenaar. Hangt samen met de draagplicht.`,zoek:['regres','regresrecht','regresvordering','verhaalsrecht']},
 {term:'Reisverzekering',uitleg:`Verzekering voor onder meer medische kosten, bagage en hulpverlening tijdens reizen. Vaak in combinatie met een annuleringsverzekering en als doorlopende polis afgesloten.`,zoek:['reisverzekering','doorlopende reisverzekering']},
 {term:'Rekening-courant DGA',uitleg:`Lopende rekening tussen een DGA en zijn vennootschap waarop onderlinge betalingen worden geboekt. Een hoge schuld aan de eigen BV kan onder de regeling voor excessief lenen vallen.`,zoek:['rekening-courant','rekening courant','rc-schuld','rekening-courantschuld']},
 {term:'Rentebedenktijd',uitleg:`Periode na afloop van de rentevaste periode, of na het uitbrengen van een offerte, waarin de klant alsnog kan kiezen voor een lager rentetarief. Duur en voorwaarden verschillen per geldverstrekker.`,zoek:['rentebedenktijd','rente bedenktijd','bedenktijd rente']},
 {term:'Rentemiddeling',uitleg:`Aanpassing van de hypotheekrente tijdens de rentevaste periode naar een nieuwe rente, waarbij de vergoeding voor vervroegde aflossing wordt verwerkt in een renteopslag in plaats van ineens betaald. Geldverstrekkers moeten de klant zorgvuldig informeren over kosten en alternatieven.`,zoek:['rentemiddeling','rente middelen','middelen rente']},
 {term:'Rentevaste periode',uitleg:`Periode waarin de rente van een leningdeel contractueel vastligt. Na afloop volgt een renteherziening; tijdens de periode kan bij extra aflossen boven het boetevrije deel een vergoeding verschuldigd zijn.`,zoek:['rentevaste periode','rentevastperiode','rentevast','rentevaste perioden']},
 {term:'Renteverlenging',uitleg:`Vaststelling van een nieuwe rente en rentevaste periode aan het einde van de lopende rentevaste periode. De geldverstrekker doet hiervoor een renteaanbod; de klant kan ook kiezen voor oversluiten.`,zoek:['renteverlenging','renteherziening','renteaanbod']},
 {term:'Reservefonds VvE',uitleg:`Spaarpot van een Vereniging van Eigenaars voor toekomstig groot onderhoud. Een VvE is wettelijk verplicht jaarlijks te reserveren, bij voorkeur op basis van een meerjarenonderhoudsplan.`,zoek:['reservefonds','reservefonds vve','onderhoudsfonds']},
 {term:'Restschuld',uitleg:`Deel van de hypotheekschuld dat na verkoop van de woning overblijft omdat de opbrengst lager is dan de schuld. Bij NHG kan onder voorwaarden een beroep worden gedaan op kwijtschelding.`,zoek:['restschuld','restschulden']},
 {term:'Restschuldregeling',uitleg:`Fiscale regeling waarbij de rente over een restschuld die is ontstaan in de periode van 29 oktober 2012 tot en met 31 december 2017 nog maximaal 15 jaar aftrekbaar is in box 1. Voor later ontstane restschulden geldt deze aftrek niet.`,zoek:['restschuldregeling','aftrek restschuld','restschuldfinanciering']},
 {term:'Risico-opslag',uitleg:`Renteopslag die een geldverstrekker hanteert op basis van het risico, meestal afhankelijk van de LTV-verhouding. Bij aflossing of waardestijging kan de klant vaak in een lagere risicoklasse vallen.`,zoek:['risico-opslag','risico-opslagen','risicoklasse']},
 {term:'Risicoprofiel',uitleg:`Inschatting van de mate waarin een klant financieel risico kan en wil dragen, gebaseerd op onder meer kennis, ervaring, financiële positie en doelstellingen. Bepalend voor de passendheid van beleggings- en hypotheekadvies.`,zoek:['risicoprofiel','risicobereidheid','risicohouding','beleggingsprofiel']},
 {term:'Roodstand',uitleg:`Mogelijkheid om tot een afgesproken limiet negatief te staan op de betaalrekening. Een roodstand vanaf een bepaalde limiet wordt bij het BKR geregistreerd.`,zoek:['roodstand','rood staan','debetstand']},
 {term:'Royement',uitleg:`Doorhalen van de inschrijving van een hypotheekrecht in het Kadaster nadat de lening volledig is afgelost. De geldverstrekker werkt daaraan mee via een notariële akte of royementsverklaring.`,zoek:['royement','royeren','doorhaling hypotheek']},
 {term:'Royementsverklaring',uitleg:`Verklaring van de vorige verzekeraar over het aantal schadevrije jaren bij een autoverzekering. Tegenwoordig grotendeels digitaal uitgewisseld tussen verzekeraars.`,zoek:['royementsverklaring','roy-data','schadevrije jaren verklaring']},
 {term:'RVU (regeling voor vervroegde uittreding)',uitleg:`Regeling waarmee werknemers enkele jaren voor de AOW-leeftijd kunnen stoppen met werken met een uitkering van de werkgever. Tot een vrijgestelde drempel is de werkgever geen RVU-heffing verschuldigd.`,zoek:['rvu','vervroegde uittreding','regeling vervroegde uittreding','rvu-heffing']},
 {term:'Samenlevingscontract',uitleg:`Schriftelijke, vaak notariële overeenkomst tussen ongehuwd samenwonenden over onder meer kosten, eigendom en verdeling bij uit elkaar gaan of overlijden. Een notarieel samenlevingscontract is onder voorwaarden nodig voor fiscaal partnerschap en voor partnerpensioen.`,zoek:['samenlevingscontract','samenlevingsovereenkomst','samenwoners','ongehuwd samenwonen']},
 {term:'Sanctiewetgeving',uitleg:`Regelgeving die financiële instellingen verplicht om relaties en transacties te screenen op personen en entiteiten op sanctielijsten. Bij een treffer moeten tegoeden worden bevroren en melding worden gedaan.`,zoek:['sanctiewet','sanctiewetgeving','sanctielijst','sanctiescreening']},
 {term:'Schade-expert',uitleg:`Deskundige die namens de verzekeraar (of de verzekerde) de oorzaak en omvang van een schade vaststelt. Bij onenigheid kan de verzekerde een eigen expert inschakelen voor een contra-expertise.`,zoek:['schade-expert','schadeexpert','schade expert']},
 {term:'Schenkbelasting',uitleg:`Belasting die de ontvanger van een schenking betaalt boven de toepasselijke vrijstelling. Tarieven en vrijstellingen hangen af van de relatie tussen schenker en ontvanger.`,zoek:['schenkbelasting','schenkingsrecht','schenken','schenking']},
 {term:'Schenkingsvrijstelling eigen woning',uitleg:`Verhoogde eenmalige vrijstelling van schenkbelasting voor schenkingen ten behoeve van de eigen woning, ook wel jubelton genoemd. De vrijstelling is per 1 januari 2024 afgeschaft.`,zoek:['jubelton','schenkingsvrijstelling eigen woning','schenkvrijstelling eigen woning']},
 {term:'Schuldhulpverlening',uitleg:`Ondersteuning, vaak via de gemeente, bij het oplossen van problematische schulden, bijvoorbeeld via een minnelijke schuldregeling met schuldeisers. Een schuldregeling wordt bij het BKR vermeld.`,zoek:['schuldhulpverlening','schuldsanering','minnelijke schuldregeling','schuldregeling']},
 {term:'Schuldigerkenning',uitleg:`Notariële of onderhandse akte waarin iemand erkent een bedrag schuldig te zijn, bijvoorbeeld na een schenking op papier. Fiscaal gelden strikte voorwaarden, onder meer over de rente en de betaling daarvan.`,zoek:['schuldigerkenning','schenking op papier','papieren schenking']},
 {term:'Second opinion',uitleg:`Toetsing van een eerder gegeven advies door een andere adviseur. Kan een klant zekerheid geven, maar de tweede adviseur moet zelf voldoende informatie inwinnen om tot een oordeel te komen.`,zoek:['second opinion','tweede mening','adviestoets']},
 {term:'SEH (Stichting Erkend Hypotheekadviseur)',uitleg:`Stichting die het register bijhoudt van Erkend Hypotheekadviseurs en andere financiële beroepstitels. Geregistreerden moeten aan opleidings- en permanente-educatie-eisen voldoen.`,zoek:['seh','erkend hypotheekadviseur','stichting erkend hypotheekadviseur']},
 {term:'SEW (spaarrekening eigen woning)',uitleg:`Geblokkeerde spaarrekening die bestemd is voor aflossing van de eigenwoningschuld, kenmerkend voor de bankspaarhypotheek. Onder overgangsrecht kon het saldo onder voorwaarden fiscaal vrijgesteld zijn.`,zoek:['sew','spaarrekening eigen woning']},
 {term:'SIRA (systematische integriteitsrisicoanalyse)',uitleg:`Periodieke analyse van de integriteitsrisico's van een financiële onderneming, zoals witwassen, fraude en belangenverstrengeling, met de beheersmaatregelen die daarbij horen. De AFM verwacht dat ook adviseurs en bemiddelaars deze analyse uitvoeren.`,zoek:['sira','integriteitsrisicoanalyse','systematische integriteitsrisicoanalyse']},
 {term:'Solidaire premieregeling',uitleg:`Premieregeling onder de Wtp waarin het vermogen collectief wordt belegd en deelnemers een persoonlijk pensioenvermogen hebben, met een solidariteitsreserve om risico's tussen generaties te delen.`,zoek:['solidaire premieregeling','solidaire premieovereenkomst','solidariteitsreserve']},
 {term:'Spaarhypotheek',uitleg:`Hypotheekvorm waarbij de lening aflossingsvrij is en gelijktijdig premie wordt betaald voor een spaarverzekering waarvan de uitkering de lening aan het einde aflost. Het rendement op de verzekering is doorgaans gelijk aan de hypotheekrente.`,zoek:['spaarhypotheek','spaarhypotheken']},
 {term:'Splitsingsakte',uitleg:`Notariële akte waarmee een gebouw juridisch wordt verdeeld in appartementsrechten, met daarbij het splitsingsreglement over rechten en plichten van de eigenaars. Bevat ook de oprichting van de VvE.`,zoek:['splitsingsakte','splitsingsreglement','splitsing']},
 {term:'Stamrecht',uitleg:`Recht op periodieke uitkeringen, bijvoorbeeld uit een ontslagvergoeding die vroeger in een stamrecht-BV kon worden ondergebracht. De stamrechtvrijstelling is in 2014 vervallen; bestaande stamrechten worden fiscaal als lijfrente behandeld.`,zoek:['stamrecht','stamrecht-bv','stamrechtvrijstelling','ontslagvergoeding']},
 {term:'Starterslening',uitleg:`Aanvullende lening voor starters, meestal verstrekt via een gemeentelijke regeling, die het verschil overbrugt tussen de aankoopkosten en de maximale hypotheek. Kenmerkend zijn gunstige voorwaarden in de eerste jaren en een periodieke inkomenstoets.`,zoek:['starterslening','startersleningen','stimuleringsregeling starters']},
 {term:'Startersvrijstelling',uitleg:`Eenmalige vrijstelling van overdrachtsbelasting voor kopers vanaf 18 jaar en jonger dan 35 jaar die een woning als hoofdverblijf gaan bewonen, mits de woningwaarde onder de geldende grens blijft. De koper moet hiervoor een verklaring afgeven bij de notaris.`,zoek:['startersvrijstelling','vrijstelling overdrachtsbelasting']},
 {term:'Stilzwijgende verlenging',uitleg:`Automatische verlenging van een overeenkomst, zoals een verzekering, als niet tijdig wordt opgezegd. Voor consumenten gelden wettelijke beperkingen aan de verlengingsduur en opzegtermijn.`,zoek:['stilzwijgende verlenging','automatische verlenging','opzegtermijn']},
 {term:'Studieschuld',uitleg:`Schuld bij DUO voor studiefinanciering. Bij de hypotheektoets wordt rekening gehouden met een maandlast die is afgeleid van de oorspronkelijke studieschuld of de werkelijke maandlast, afhankelijk van de geldende normen.`,zoek:['studieschuld','studieschulden','duo-schuld','studielening']},
 {term:'Swaprente',uitleg:`Rente waartegen banken onderling vaste en variabele rentestromen ruilen; een veelgebruikte maatstaf voor de financieringskosten van geldverstrekkers bij hypotheken met een rentevaste periode.`,zoek:['swaprente','swap-rente','swaptarief']},
 {term:'Taxatie',uitleg:`Waardebepaling van een woning door een onafhankelijke, gecertificeerde taxateur, vastgelegd in een gevalideerd taxatierapport. De vastgestelde marktwaarde is de basis voor de maximale lening.`,zoek:['taxatie','taxatierapport','taxatierapporten','taxateur']},
 {term:'Tegenbewijsregeling box 3',uitleg:`Regeling waarmee een belastingplichtige aannemelijk kan maken dat zijn werkelijke rendement in box 3 lager is dan het forfaitaire rendement. In dat geval wordt het werkelijke rendement belast.`,zoek:['tegenbewijsregeling','werkelijk rendement','tegenbewijs box 3']},
 {term:'Testament',uitleg:`Notariële akte waarin iemand vastlegt wat er na zijn overlijden met zijn nalatenschap gebeurt, in afwijking van het wettelijke erfrecht. Kan bijvoorbeeld een langstlevende-regeling, legaten of een executeur bevatten.`,zoek:['testament','testamentair','uiterste wil']},
 {term:'TMO (taxatiemanagementorganisatie)',uitleg:`Organisatie die namens geldverstrekkers taxatieopdrachten verdeelt aan onafhankelijke taxateurs en de kwaliteit bewaakt. Bedoeld om belangenverstrengeling tussen verkopend makelaar en taxateur te voorkomen.`,zoek:['tmo','taxatiemanagementorganisatie','taxatie management organisatie']},
 {term:'Toeslagen',uitleg:`Inkomensafhankelijke tegemoetkomingen van de overheid, zoals huurtoeslag, zorgtoeslag, kinderopvangtoeslag en kindgebonden budget. Een wijziging in inkomen of vermogen kan leiden tot terugbetaling.`,zoek:['toeslagen','huurtoeslag','zorgtoeslag','kindgebonden budget','kinderopvangtoeslag']},
 {term:'Toeslagenwet',uitleg:`Wet die een aanvulling geeft op een werknemersuitkering, zoals WW, WIA of Ziektewet, als het totale inkomen onder het sociaal minimum komt. Uitgevoerd door het UWV.`,zoek:['toeslagenwet','tw-toeslag']},
 {term:'Toestemming echtgenoot (art. 1:88 BW)',uitleg:`Wettelijke eis dat een gehuwde of geregistreerde partner voor bepaalde rechtshandelingen toestemming van de ander nodig heeft, zoals het verkopen of met hypotheek bezwaren van de gezamenlijk bewoonde woning en borgstelling. Zonder toestemming is de handeling vernietigbaar.`,zoek:['1:88','artikel 1:88','toestemming partner','toestemming echtgenoot','medeondertekening']},
 {term:'Toetsinkomen',uitleg:`Inkomen waarmee de geldverstrekker de maximale financieringslast bepaalt, vastgesteld volgens de normen voor onder meer werknemers, ondernemers en gepensioneerden. Bij twee aanvragers worden de inkomens volgens de geldende normen gecombineerd.`,zoek:['toetsinkomen','toetsinkomens']},
 {term:'Toetsrente',uitleg:`Rente waarmee de maximale hypotheek wordt berekend. Bij een korte rentevaste periode geldt volgens de leennormen een hogere minimale toetsrente om renterisico op te vangen.`,zoek:['toetsrente']},
 {term:'Toezichtheffing',uitleg:`Bijdrage die financiële ondernemingen jaarlijks betalen voor de kosten van het toezicht door de AFM en DNB. De hoogte hangt af van de toezichtcategorie en de omvang van de onderneming.`,zoek:['toezichtheffing','heffing afm','kostenheffing']},
 {term:'Trhk (Tijdelijke regeling hypothecair krediet)',uitleg:`Ministeriële regeling waarin de leennormen voor hypothecair krediet zijn vastgelegd, waaronder de financieringslastpercentages, de maximale LTV en de mogelijkheid tot explain. De regeling wordt periodiek geactualiseerd.`,zoek:['trhk','tijdelijke regeling hypothecair krediet']},
 {term:'Tussenpersoon',uitleg:`Onafhankelijke of gebonden adviseur of bemiddelaar die tussen consument en aanbieder van financiële producten staat. Moet beschikken over een Wft-vergunning of werken onder verantwoordelijkheid van een vergunninghouder.`,zoek:['tussenpersoon','tussenpersonen','assurantietussenpersoon']},
 {term:'Tweede woning',uitleg:`Woning die niet als hoofdverblijf dient, zoals een recreatiewoning of beleggingspand. Fiscaal valt deze in box 3; financiering vindt plaats tegen andere normen dan voor de eigen woning.`,zoek:['tweede woning','recreatiewoning','vakantiewoning','tweede huis']},
 {term:'UBO (uiteindelijk belanghebbende)',uitleg:`Natuurlijk persoon die uiteindelijk eigenaar is van of zeggenschap heeft over een organisatie. Bij zakelijke klanten moet in het kader van de Wwft de UBO worden vastgesteld en geverifieerd.`,zoek:['ubo','uiteindelijk belanghebbende','ultimate beneficial owner','ubo-register']},
 {term:'Uitbesteding',uitleg:`Laten uitvoeren van werkzaamheden door een derde, zoals administratie, ICT of backoffice. De financiële onderneming blijft verantwoordelijk voor de naleving van de regels en moet de uitbesteding beheerst inrichten.`,zoek:['uitbesteding','uitbesteden','outsourcing']},
 {term:'Uitkeringsovereenkomst',uitleg:`Pensioenregeling waarin de hoogte van de pensioenuitkering vooraf is toegezegd, bijvoorbeeld als middelloon- of eindloonregeling. Met de Wtp verdwijnen deze regelingen voor nieuwe opbouw.`,zoek:['uitkeringsovereenkomst','db-regeling','middelloonregeling','eindloonregeling','middelloon','eindloon']},
 {term:'Uitruil',uitleg:`Keuze om in een pensioenregeling partnerpensioen om te zetten in een hoger ouderdomspensioen of omgekeerd. Uitruil van partnerpensioen vraagt in de regel toestemming van de partner.`,zoek:['uitruil','uitruilen','uitruilmogelijkheid']},
 {term:'Uitsluiting',uitleg:`Bepaling in de polisvoorwaarden die bepaalde oorzaken of situaties van dekking uitsluit, zoals opzet, molest of slijtage. Belangrijk om bij advies en schadebehandeling expliciet te benoemen.`,zoek:['uitsluiting','uitsluitingen','niet verzekerd']},
 {term:'Uitvaartverzekering',uitleg:`Verzekering die de kosten van een uitvaart dekt, in de vorm van een kapitaal- of naturaverzekering. Belangrijk is dat de verzekerde waarde aansluit bij de verwachte kosten.`,zoek:['uitvaartverzekering','uitvaartverzekeringen']},
 {term:'Unit-linked verzekering',uitleg:`Beleggingsverzekering waarbij de premie, na aftrek van kosten en risicopremie, wordt belegd in beleggingsfondsen. De uitkering hangt af van het rendement; kostenstructuren waren aanleiding tot de woekerpolisaffaire.`,zoek:['unit-linked','beleggingsverzekering','beleggingspolis']},
 {term:'UPO (Uniform Pensioenoverzicht)',uitleg:`Jaarlijks overzicht van de pensioenuitvoerder met de opgebouwde en te bereiken pensioenaanspraken in een gestandaardiseerd format. Een belangrijke bron bij pensioen- en nabestaandenanalyses.`,zoek:['upo','uniform pensioenoverzicht','pensioenoverzicht']},
 {term:'Urencriterium',uitleg:`Eis dat een ondernemer ten minste 1.225 uur per kalenderjaar aan zijn onderneming besteedt, en meer dan de helft van zijn arbeidstijd. Voorwaarde voor onder meer de zelfstandigenaftrek en de FOR.`,zoek:['urencriterium','1225 uur','1.225 uur']},
 {term:'UWV (Uitvoeringsinstituut Werknemersverzekeringen)',uitleg:`Uitvoeringsorganisatie voor werknemersverzekeringen zoals WW en WIA. De polisadministratie van UWV wordt gebruikt voor inkomensbepaling via IBL.`,zoek:['uwv','uitvoeringsinstituut werknemersverzekeringen']},
 {term:'UWV-verzekeringsbericht',uitleg:`Overzicht van de bij het UWV bekende loon- en dienstverbandgegevens van een werknemer. Is de basis voor de inkomensbepaling via IBL bij een hypotheekaanvraag.`,zoek:['verzekeringsbericht','uwv-verzekeringsbericht','verzekeringsbericht uwv','polisadministratie']},
 {term:'Vakbekwaamheid',uitleg:`Wettelijke eis dat medewerkers die klantcontact hebben over financiële producten beschikken over de vereiste kennis en vaardigheden, aangetoond met Wft-diploma en PE. De eisen verschillen per productdomein.`,zoek:['vakbekwaamheid','wft-diploma','wft-examen','wft basis','wft-diploma\'s']},
 {term:'Variabele rente',uitleg:`Hypotheekrente zonder rentevaste periode, die de geldverstrekker tussentijds kan aanpassen. Bij toetsing van de maximale lening geldt dan een voorgeschreven toetsrente.`,zoek:['variabele rente','variabel']},
 {term:'Verbond van Verzekeraars',uitleg:`Branchevereniging van verzekeraars in Nederland. Stelt onder meer gedragscodes en protocollen op, zoals het Protocol Verzekeringskeuringen en de Gedragscode Verwerking Persoonsgegevens.`,zoek:['verbond van verzekeraars','verbond']},
 {term:'Vergelijkingskaart',uitleg:`Door de AFM voorgeschreven informatiekaart die sinds 1 april 2023 het dienstverleningsdocument vervangt. Bij advies over en bemiddeling in producten onder het provisieverbod, zoals hypotheken, overlijdensrisico-, arbeidsongeschiktheids-, uitvaart- en pensioenverzekeringen, geef je de consument de kaart uiterlijk voordat je advies geeft of bemiddelt. De kaart beschrijft de aard en omvang van je dienstverlening, je onafhankelijkheid, je kosten en eventuele belangen; je biedt hem ook aan op je website. Andere wettelijke informatie, zoals je klachtenprocedure, Kifid-aansluiting en AFM-registratie, geef je de klant daarnaast, bijvoorbeeld via je website of opdrachtbevestiging.`,zoek:['vergelijkingskaart','vergelijkingskaarten','dienstverleningsdocument','dvd']},
 {term:'Verhuisregeling',uitleg:`Voorwaarde in een hypotheekovereenkomst waarmee de klant bij verhuizing de bestaande lening en rente kan meenemen naar een nieuwe woning, ook wel meeneemregeling genoemd. Voorwaarden verschillen per geldverstrekker.`,zoek:['verhuisregeling','meeneemregeling','hypotheek meenemen']},
 {term:'Verklaring van erfrecht',uitleg:`Notariële verklaring waarin staat wie de erfgenamen zijn en wie bevoegd is de nalatenschap af te wikkelen. Banken en verzekeraars vragen deze verklaring vaak voordat zij tegoeden of uitkeringen vrijgeven.`,zoek:['verklaring van erfrecht','verklaring van executele','erfrechtverklaring']},
 {term:'Vermogensbeheer',uitleg:`Dienst waarbij een vermogensbeheerder op basis van een mandaat zelfstandig beleggingsbeslissingen neemt voor de klant. Vereist een vergunning als beleggingsonderneming.`,zoek:['vermogensbeheer','vermogensbeheerder','discretionair beheer']},
 {term:'Verpanding',uitleg:`Zekerheidsrecht waarbij de rechten uit een polis of rekening aan de geldverstrekker worden verpand, bijvoorbeeld bij een ORV of kapitaalverzekering die de hypotheek moet aflossen. De uitkering wordt dan eerst aangewend voor aflossing.`,zoek:['verpanding','verpandingsverklaring','verpande polis']},
 {term:'Verrekenbeding',uitleg:`Afspraak in huwelijkse voorwaarden om bepaalde inkomsten of vermogensaanwas periodiek of bij einde van het huwelijk met elkaar te verrekenen. Een niet-nagekomen periodiek verrekenbeding kan bij scheiding verstrekkende gevolgen hebben.`,zoek:['verrekenbeding','periodiek verrekenbeding','finaal verrekenbeding']},
 {term:'Verscherpt cliëntenonderzoek',uitleg:`Uitgebreider cliëntenonderzoek dat de Wwft voorschrijft bij een verhoogd risico op witwassen of terrorismefinanciering, zoals bij PEP's of bij cliënten uit risicolanden. Kan extra vragen naar de herkomst van vermogen omvatten.`,zoek:['verscherpt cliëntenonderzoek','verscherpt clientenonderzoek','edd','herkomst van middelen','herkomst vermogen']},
 {term:'Verwerkersovereenkomst',uitleg:`Overeenkomst die op grond van de AVG verplicht is wanneer een partij, zoals een softwareleverancier, persoonsgegevens verwerkt in opdracht van de verwerkingsverantwoordelijke. Legt afspraken vast over beveiliging, geheimhouding en datalekken.`,zoek:['verwerkersovereenkomst','verwerker','verwerkingsverantwoordelijke']},
 {term:'Verwerkingsregister',uitleg:`Verplicht overzicht onder de AVG van de verwerkingen van persoonsgegevens binnen een organisatie, met onder meer het doel, de categorieën gegevens en bewaartermijnen.`,zoek:['verwerkingsregister','register van verwerkingsactiviteiten']},
 {term:'Verwerping nalatenschap',uitleg:`Weigering van een erfgenaam om een nalatenschap te aanvaarden, via een verklaring bij de rechtbank. De erfgenaam krijgt dan geen bezittingen, maar is ook niet aansprakelijk voor schulden.`,zoek:['verwerping','verwerpen nalatenschap','erfenis verwerpen']},
 {term:'Verzekerde',uitleg:`Persoon op wiens leven, gezondheid of aansprakelijkheid een verzekering betrekking heeft. Kan een ander zijn dan de verzekeringnemer, bijvoorbeeld bij een kruislingse ORV.`,zoek:['verzekerde']},
 {term:'Verzekeringnemer',uitleg:`Partij die de verzekeringsovereenkomst sluit en de premie verschuldigd is. Bepaalt in principe de begunstiging en kan de polis wijzigen of beëindigen.`,zoek:['verzekeringnemer','polishouder']},
 {term:'Verzilverhypotheek',uitleg:`Hypotheek, meestal voor senioren, waarmee overwaarde van de eigen woning wordt vrijgemaakt zonder verplichte maandlasten; rente wordt bijgeschreven op de lening. De schuld wordt afgelost bij verkoop van de woning of overlijden.`,zoek:['verzilverhypotheek','verzilverlening','overwaardehypotheek','opeethypotheek']},
 {term:'Verzuimverzekering',uitleg:`Verzekering voor werkgevers die de kosten van loondoorbetaling bij ziekte van werknemers (gedeeltelijk) dekt, vaak in combinatie met arbodienstverlening.`,zoek:['verzuimverzekering','ziekteverzuimverzekering']},
 {term:'VFN (Vereniging van Financieringsondernemingen in Nederland)',uitleg:`Branchevereniging van aanbieders van consumptief krediet en lease. Stelt gedragscodes op, bijvoorbeeld over verantwoorde kredietverlening en leennormen voor consumptief krediet.`,zoek:['vfn','vereniging van financieringsondernemingen']},
 {term:'Volmacht',uitleg:`Bevoegdheid van een gevolmachtigd agent om namens een verzekeraar verzekeringen te accepteren, polissen op te maken en schaden af te handelen. Voor volmachtbedrijven gelden aanvullende eisen.`,zoek:['volmacht','gevolmachtigd agent','volmachtbedrijf']},
 {term:'Voorlopige aanslag',uitleg:`Aanslag of teruggaaf die de Belastingdienst vooraf oplegt op basis van een schatting van het inkomen. Hiermee kan de hypotheekrenteaftrek al maandelijks worden verrekend.`,zoek:['voorlopige aanslag','voorlopige teruggaaf','maandelijkse teruggaaf']},
 {term:'Voorwaarden & Normen (NHG)',uitleg:`Regels van de Stichting WEW die bepalen onder welke voorwaarden een lening met Nationale Hypotheek Garantie kan worden verstrekt en wanneer aanspraak op de garantie bestaat. Worden periodiek geactualiseerd.`,zoek:['voorwaarden en normen','voorwaarden & normen','nhg-voorwaarden','nhg voorwaarden']},
 {term:'Vrij op naam (v.o.n.)',uitleg:`Koopprijs waarin de kosten voor de overdracht, zoals overdrachtsbelasting en notariskosten voor de levering, al zijn inbegrepen. Gebruikelijk bij nieuwbouw; de kosten voor de hypotheekakte komen wel voor rekening van de koper.`,zoek:['vrij op naam','v.o.n.','von']},
 {term:'Vruchtgebruik',uitleg:`Zakelijk recht om een goed van een ander te gebruiken en de opbrengsten ervan te genieten. Komt voor in erfrecht en schenkingen, waarbij de bloot eigenaar de eigendom houdt zonder het genot.`,zoek:['vruchtgebruik','vruchtgebruiker','bloot eigendom','blote eigendom']},
 {term:'VvE (Vereniging van Eigenaars)',uitleg:`Vereniging waarvan alle eigenaars van appartementsrechten in een gebouw verplicht lid zijn. De VvE beheert de gemeenschappelijke delen, stelt de bijdragen vast en beheert het reservefonds.`,zoek:['vve','vereniging van eigenaars','vve-bijdrage','servicekosten']},
 {term:'WA-verzekering (WAM)',uitleg:`Wettelijk verplichte verzekering voor de aansprakelijkheid voor schade die met een motorrijtuig aan anderen wordt toegebracht, op grond van de Wet aansprakelijkheidsverzekering motorrijtuigen.`,zoek:['wa-verzekering','wam','wa verzekering','wet aansprakelijkheidsverzekering motorrijtuigen']},
 {term:'Waarborgsom',uitleg:`Zekerheid die de koper na ondertekening van de koopovereenkomst stelt, meestal een percentage van de koopsom. Wordt gestort bij de notaris of vervangen door een bankgarantie.`,zoek:['waarborgsom','waarborg']},
 {term:'Waardeoverdracht',uitleg:`Overdracht van opgebouwd pensioen van de oude naar de nieuwe pensioenuitvoerder bij wisseling van werkgever. Klein pensioen wordt onder voorwaarden automatisch overgedragen.`,zoek:['waardeoverdracht','pensioen overdragen','klein pensioen']},
 {term:'Werkgeversverklaring',uitleg:`Gestandaardiseerde verklaring van de werkgever over het inkomen en dienstverband van een werknemer, met zo nodig een intentieverklaring bij een tijdelijk contract. Wordt gebruikt om het toetsinkomen vast te stellen naast of in plaats van IBL.`,zoek:['werkgeversverklaring','werkgeversverklaringen','intentieverklaring']},
 {term:'Wet Hillen',uitleg:`Fiscale aftrek voor huiseigenaren met geen of een geringe eigenwoningschuld, waarbij het eigenwoningforfait hoger is dan de aftrekbare kosten. De aftrek wordt sinds 2019 in 30 jaar geleidelijk afgebouwd.`,zoek:['wet hillen','hillen-aftrek','aftrek wegens geen of geringe eigenwoningschuld']},
 {term:'Wet verbetering poortwachter',uitleg:`Wet die de verplichtingen van werkgever en werknemer bij ziekte en re-integratie regelt gedurende de eerste twee ziektejaren. Het UWV toetst het re-integratieverslag bij de WIA-aanvraag.`,zoek:['poortwachter','wet verbetering poortwachter','re-integratie','plan van aanpak']},
 {term:'Wettelijke rente',uitleg:`Door de overheid vastgestelde rente die een schuldenaar verschuldigd is bij te late betaling. Wordt ook gebruikt als referentie in andere regelingen, zoals het maximum voor de kredietvergoeding.`,zoek:['wettelijke rente','wettelijke handelsrente']},
 {term:'Wettelijke verdeling',uitleg:`Regeling in het erfrecht waarbij de langstlevende echtgenoot alle bezittingen en schulden verkrijgt en de kinderen een geldvordering krijgen die in de regel pas opeisbaar is na overlijden van de langstlevende. Geldt als er geen testament is dat iets anders bepaalt.`,zoek:['wettelijke verdeling','ouderlijke boedelverdeling']},
 {term:'WEW (Stichting Waarborgfonds Eigen Woningen)',uitleg:`Stichting die de Nationale Hypotheek Garantie uitvoert. Het Rijk en de gemeenten staan achter het fonds als achtervang.`,zoek:['wew','stichting wew']},
 {term:'Wft (Wet op het financieel toezicht)',uitleg:`Kernwet voor het toezicht op de financiële sector in Nederland, met regels voor prudentieel toezicht en gedragstoezicht. Adviseurs en bemiddelaars hebben op grond van de Wft een vergunning nodig en moeten voldoen aan gedragsregels.`,zoek:['wft','wet op het financieel toezicht','wft-vergunning']},
 {term:'Wft-register',uitleg:`Openbaar register van de AFM waarin financiële ondernemingen met een vergunning of vrijstelling zijn opgenomen. Hiermee kan een consument controleren of een adviseur bevoegd is.`,zoek:['wft-register','afm-register','register afm']},
 {term:'Wft-vergunning',uitleg:`Vergunning van de AFM die nodig is om te adviseren of te bemiddelen in financiële producten. Voorwaarden zijn onder meer vakbekwaamheid, betrouwbaarheid, een beroepsaansprakelijkheidsverzekering en aansluiting bij het Kifid.`,zoek:['wft-vergunning','vergunning afm','afm-vergunning','vergunningplicht']},
 {term:'WGA (Werkhervatting Gedeeltelijk Arbeidsgeschikten)',uitleg:`WIA-regeling voor werknemers die gedeeltelijk of tijdelijk volledig arbeidsongeschikt zijn. Na een loongerelateerde fase kan het inkomen sterk dalen, afhankelijk van de mate waarin de resterende verdiencapaciteit wordt benut.`,zoek:['wga','werkhervatting gedeeltelijk arbeidsgeschikten','wga-uitkering','loongerelateerde uitkering']},
 {term:'WGA-hiaatverzekering',uitleg:`Verzekering die het inkomensverlies aanvult wanneer een gedeeltelijk arbeidsongeschikte werknemer na de loongerelateerde fase in een lagere WGA-vervolguitkering terechtkomt. Wordt vaak door de werkgever collectief aangeboden.`,zoek:['wga-hiaat','wga hiaat','wga-gat']},
 {term:'WIA (Wet werk en inkomen naar arbeidsvermogen)',uitleg:`Werknemersverzekering die na twee jaar ziekte een uitkering kan geven, onderverdeeld in de WGA voor gedeeltelijk arbeidsongeschikten en de IVA voor volledig en duurzaam arbeidsongeschikten. Het WIA-hiaat kan met een aanvullende verzekering worden afgedekt.`,zoek:['wia','wga','iva','wia-hiaat']},
 {term:'WIA-excedentverzekering',uitleg:`Verzekering die arbeidsongeschiktheidsdekking biedt voor het deel van het loon boven het maximumdagloon van de WIA. Relevant voor werknemers met een hoger salaris.`,zoek:['wia-excedent','excedentverzekering','wia excedent']},
 {term:'Woekerpolis',uitleg:`Verzamelnaam voor beleggingsverzekeringen met hoge en onvoldoende transparante kosten. Verzekeraars hebben compensatieregelingen getroffen en er zijn diverse collectieve procedures gevoerd.`,zoek:['woekerpolis','woekerpolissen','compensatieregeling']},
 {term:"Woningcijfer",uitleg:`Cijfer van 1 tot 10 voor de bouwkundige staat en de omgeving van een woning, uit openbare registers, met bandbreedte en herkomsttabel. Geen taxatie en geen advies. Zie k350.`,zoek:['woningcijfer','woningcijfer.nl']},
 {term:'Woningwaarderingsstelsel',uitleg:`Puntensysteem waarmee de maximale huurprijs van een huurwoning wordt bepaald op basis van onder meer oppervlakte, voorzieningen, energielabel en WOZ-waarde. Is sinds de Wet betaalbare huur ook bepalend voor het middensegment.`,zoek:['woningwaarderingsstelsel','wws','puntenstelsel','wet betaalbare huur']},
 {term:'Woonboot',uitleg:`Schip of drijvend object dat permanent als woning wordt gebruikt. Financiering is mogelijk bij een beperkt aantal geldverstrekkers; een vaste ligplaats en registratie zijn daarbij belangrijke voorwaarden.`,zoek:['woonboot','woonark','ligplaats']},
 {term:'Woonlastenverzekering',uitleg:`Verzekering die bij arbeidsongeschiktheid en/of onvrijwillige werkloosheid gedurende een beperkte periode een uitkering doet ter dekking van de woonlasten. Eigenrisicotermijn, uitkeringsduur en uitsluitingen zijn belangrijke aandachtspunten.`,zoek:['woonlastenverzekering','woonlastenverzekeringen','woonlastenbeschermer']},
 {term:'Woonquote',uitleg:`Ander woord voor het deel van het inkomen dat aan woonlasten mag of wordt besteed. In de leennormen uitgedrukt als financieringslastpercentage.`,zoek:['woonquote','woonquotes']},
 {term:'WOZ-waarde',uitleg:`Waarde van onroerend goed die de gemeente jaarlijks vaststelt op grond van de Wet waardering onroerende zaken. Dient onder meer als grondslag voor het eigenwoningforfait en de onroerendezaakbelasting.`,zoek:['woz','woz-waarde','woz-beschikking']},
 {term:'Wsnp (Wet schuldsanering natuurlijke personen)',uitleg:`Wettelijke schuldsaneringsregeling die de rechter kan uitspreken als een minnelijke regeling niet lukt. Na succesvolle afronding krijgt de schuldenaar een schone lei.`,zoek:['wsnp','wettelijke schuldsanering','schone lei']},
 {term:'Wtp (Wet toekomst pensioenen)',uitleg:`Wet die het Nederlandse pensioenstelsel hervormt naar premieovereenkomsten met een directere koppeling tussen ingelegde premie, rendement en pensioen. Bestaande aanspraken kunnen worden ingevaren in de nieuwe regeling.`,zoek:['wtp','wet toekomst pensioenen','nieuwe pensioenstelsel','invaren']},
 {term:'WW (Werkloosheidswet)',uitleg:`Werknemersverzekering die een tijdelijke uitkering geeft bij werkloosheid. De duur hangt af van het arbeidsverleden; geldverstrekkers houden bij de toetsing rekening met lopende of verwachte WW.`,zoek:['ww','werkloosheidswet','ww-uitkering']},
 {term:'Wwft (Wet ter voorkoming van witwassen en financieren van terrorisme)',uitleg:`Wet die instellingen, waaronder bepaalde financiële dienstverleners, verplicht tot cliëntenonderzoek en het melden van ongebruikelijke transacties bij de FIU-Nederland.`,zoek:['wwft','witwaswet','anti-witwas','ongebruikelijke transactie']},
 {term:'Zelfstandigenaftrek',uitleg:`Aftrekpost voor IB-ondernemers die aan het urencriterium voldoen. Het bedrag wordt de komende jaren stapsgewijs verlaagd.`,zoek:['zelfstandigenaftrek']},
 {term:'Ziektewet',uitleg:`Wet die een uitkering geeft aan zieke werknemers zonder werkgever die het loon doorbetaalt, zoals flexwerkers en mensen met een WW-uitkering. Uitgevoerd door het UWV.`,zoek:['ziektewet','zw-uitkering','vangnetter']},
 {term:'Zorgplicht',uitleg:`Wettelijke verplichting voor financiële dienstverleners om zorgvuldig de belangen van de klant te behartigen, met als uitgangspunt het klantbelang. Schending kan leiden tot aansprakelijkheid en toezichtmaatregelen.`,zoek:['zorgplicht','bijzondere zorgplicht','klantbelang']},
 {term:'Zorgverzekering',uitleg:`Verplichte basisverzekering voor zorgkosten op grond van de Zorgverzekeringswet, met daarnaast optionele aanvullende verzekeringen. Voor de basisverzekering geldt een wettelijk verplicht eigen risico.`,zoek:['zorgverzekering','basisverzekering','aanvullende verzekering','zvw']},
 {term:'ZZP (zelfstandige zonder personeel)',uitleg:`Ondernemer die zonder personeel werkt. Bij een hypotheekaanvraag wordt het inkomen doorgaans vastgesteld met een inkomensverklaring ondernemer en is een eigen voorziening voor arbeidsongeschiktheid en pensioen een aandachtspunt.`,zoek:['zzp','zzp-er','zelfstandige zonder personeel']}
];
